import sys
sys.setrecursionlimit(100000)

# types as tuples
NAT=('nat',); TOP=('top',); NIL=('nil',)
def b(i): return ('b',i)
def v(x): return ('v',x)
def arr(a,c): return ('arr',a,c)
def allt(a,c): return ('all',a,c)
def mu(a): return ('mu',a)
def lab(l,a): return ('lab',l,a)
def cons(i,a,c): return ('cons',i,a,c)

def size(T):
    t=T[0]
    if t in ('nat','top','nil','b','v'): return 1
    if t=='arr' or t=='all': return 1+size(T[1])+size(T[2])
    if t=='mu': return 1+size(T[1])
    if t=='lab': return 1+size(T[2])
    if t=='cons': return 1+size(T[2])+size(T[3])

def open_tt_rec(K,U,T):
    t=T[0]
    if t in ('nat','top','nil'): return T
    if t=='b': return U if K==T[1] else T
    if t=='v': return T
    if t=='arr': return arr(open_tt_rec(K,U,T[1]),open_tt_rec(K,U,T[2]))
    if t=='all': return allt(open_tt_rec(K,U,T[1]),open_tt_rec(K+1,U,T[2]))
    if t=='mu': return mu(open_tt_rec(K+1,U,T[1]))
    if t=='lab': return lab(T[1],open_tt_rec(K,U,T[2]))
    if t=='cons': return cons(T[1],open_tt_rec(K,U,T[2]),open_tt_rec(K,U,T[3]))
def open_tt(T,U): return open_tt_rec(0,U,T)

def fv_tt(T):
    t=T[0]
    if t in ('nat','top','nil','b'): return set()
    if t=='v': return {T[1]}
    if t=='arr' or t=='all': return fv_tt(T[1])|fv_tt(T[2])
    if t=='mu': return fv_tt(T[1])
    if t=='lab': return fv_tt(T[2])
    if t=='cons': return fv_tt(T[2])|fv_tt(T[3])

def fl_tt(T):
    t=T[0]
    if t in ('nat','top','nil','b','v'): return set()
    if t=='arr' or t=='all': return fl_tt(T[1])|fl_tt(T[2])
    if t=='mu': return fl_tt(T[1])
    if t=='lab': return {T[1]}|fl_tt(T[2])
    if t=='cons': return {T[1]}|fl_tt(T[2])|fl_tt(T[3])

def collectLabel(T):
    t=T[0]
    if t=='cons': return {T[1]}|collectLabel(T[3])
    return set()
def Tlookup(i,T):
    t=T[0]
    if t=='cons':
        if T[1]==i: return T[2]
        return Tlookup(i,T[3])
    return None
def rt_type(T): return T[0] in ('nil','cons')

class Ctx:
    def __init__(self): self.c=0
    def fresh(self, avoid):
        while True:
            x=self.c; self.c+=1
            if x not in avoid: return x
C=Ctx()

def atoms_of(T): return fv_tt(T)|fl_tt(T)
def atoms_env(E):
    s=set()
    for (x,k,T) in E: s|={x}|atoms_of(T)
    return s

def wf_env(E):
    # list head = most recent
    if not E: return True
    (x,k,T)=E[0]
    rest=E[1:]
    if x in {y for (y,_,_) in rest}: return False
    if not wf_env(rest): return False
    return wf_dec(rest,T)

def wf_dec(E,T):
    t=T[0]
    if t in ('top','nat','nil'): return True
    if t=='v':
        return any(y==T[1] and k=='sub' for (y,k,_) in E)
    if t=='arr': return wf_dec(E,T[1]) and wf_dec(E,T[2])
    if t=='lab': return wf_dec(E,T[2])
    if t=='cons': return wf_dec(E,T[2]) and wf_dec(E,T[3]) and rt_type(T[3]) and (T[1] not in collectLabel(T[3]))
    if t=='all':
        if not wf_dec(E,T[1]): return False
        avoid=atoms_env(E)|atoms_of(T[1])|atoms_of(T[2])
        X=C.fresh(avoid)
        return wf_dec([(X,'sub',T[1])]+E, open_tt(T[2],v(X)))
    if t=='mu':
        avoid=atoms_env(E)|atoms_of(T[1])
        X=C.fresh(avoid)
        E2=[(X,'sub',TOP)]+E
        P=open_tt(T[1],v(X)); Q=open_tt(T[1],lab(X,P))
        return wf_dec(E2,P) and wf_dec(E2,Q)
    return False

def binds(E,X):
    for (y,k,T) in E:
        if y==X: return (k,T)
    return None

depth_exceeded=[False]
MAXD=5000

def sub_dec(E,A,B,depth=0, trace=None):
    if depth>MAXD:
        depth_exceeded[0]=True
        return False
    if trace is not None:
        trace.append((depth,E,A,B))
    if not wf_env(E): return False
    if B==TOP:
        return wf_dec(E,A)
    t=A[0]
    if t=='nat': return B==NAT
    if t=='top': return False
    if t=='v':
        X=A[1]
        if B==A and wf_dec(E,A): return True
        bb=binds(E,X)
        if bb is not None and bb[0]=='sub':
            return sub_dec(E,bb[1],B,depth+1,trace)
        return False
    if t=='arr':
        if B[0]!='arr': return False
        return sub_dec(E,B[1],A[1],depth+1,trace) and sub_dec(E,A[2],B[2],depth+1,trace)
    if t=='all':
        if B[0]!='all': return False
        S1,T1=A[1],A[2]; S2,T2=B[1],B[2]
        if not (sub_dec(E,S1,S2,depth+1,trace) and sub_dec(E,S2,S1,depth+1,trace)): return False
        avoid=atoms_env(E)|atoms_of(A)|atoms_of(B)
        X=C.fresh(avoid)
        return sub_dec([(X,'sub',S2)]+E, open_tt(T1,v(X)), open_tt(T2,v(X)),depth+1,trace)
    if t=='mu':
        if B[0]!='mu': return False
        A1,A2=A[1],B[1]
        avoid=atoms_env(E)|atoms_of(A)|atoms_of(B)
        X=C.fresh(avoid)
        E2=[(X,'sub',TOP)]+E
        P1=open_tt(A1,v(X)); P2=open_tt(A2,v(X))
        L1=lab(X,P1); L2=lab(X,P2)
        U1=open_tt(A1,L1); U2=open_tt(A2,L2)
        if not (wf_dec(E2,U1) and wf_dec(E2,U2)): return False
        return sub_dec(E2,U1,U2,depth+1,trace)
    if t=='lab':
        if B[0]!='lab': return False
        if A[1]!=B[1]: return False
        return sub_dec(E,A[2],B[2],depth+1,trace)
    if t=='cons':
        if B[0]!='cons': return False
        if not (rt_type(A) and rt_type(B)): return False
        if not collectLabel(B)<=collectLabel(A): return False
        if not (wf_dec(E,A) and wf_dec(E,B)): return False
        # for all labels
        labs=collectLabel(B)
        for i in labs:
            t1=Tlookup(i,A); t2=Tlookup(i,B)
            if t1 is not None and t2 is not None:
                if not sub_dec(E,t1,t2,depth+1,trace): return False
        return True
    if t=='nil':
        if B[0]!='nil': return False
        return True
    return False

def V(n): return v(1000+n)
def L(n,T): return lab(1000+n,T)

# examples: mu X. X->nat  vs mu X. X->top
A=mu(arr(b(0),NAT))
B=mu(arr(b(0),TOP))
tr=[]
r=sub_dec([],A,B,trace=tr)
print("ex1",r,"depth",len(tr)-1,"maxdepth",max(x[0] for x in tr))
# identical
tr=[]
print("ex2",sub_dec([],A,A,trace=tr), "maxdepth",max(x[0] for x in tr))
# nested mu: mu X. mu Y. X->Y vs itself
C1=mu(mu(arr(b(1),b(0))))
tr=[]
print("ex3",sub_dec([],C1,C1,trace=tr),"maxdepth",max(x[0] for x in tr))
# mu X. mu Y. (X -> Y) vs mu X. mu Y. (X -> nat)
C2=mu(mu(arr(b(1),NAT)))
tr=[]
print("ex4",sub_dec([],C1,C2,trace=tr),"maxdepth",max(x[0] for x in tr))
print("exceeded",depth_exceeded[0])
