import random, time
random.seed(7)
def rnd(d, nv):
    if d<=0:
        return random.choice([NAT,TOP,b(0),v(nv+random.randrange(3))])
    t=random.randrange(8)
    if t==0: return NAT
    if t==1: return b(0)
    if t==2: return arr(rnd(d-1,nv),rnd(d-1,nv))
    if t==3: return mu(rnd(d-1,nv+1))  # note: inside mu, our vars are b(0) as bound; approximate
    if t==4: return allt(rnd(d-1,nv),rnd(d-1,nv+1))
    if t==5: return lab(random.randrange(3),rnd(d-1,nv))
    if t==6: return cons(random.randrange(3),rnd(d-1,nv),rnd(d-1,nv))
    return TOP

maxtot=0
worst=None
for trial in range(300):
    A=rnd(4,50); B=rnd(4,50)
    tr=[]
    try:
        t0=time.time(); r=sub_dec([],A,B,trace=tr); dt=time.time()-t0
    except RecursionError:
        print("RECURSION ERROR"); print(A,B); break
    md=max((x[0] for x in tr),default=0)
    if md>maxtot: maxtot=md; worst=(A,B,dt)
