def pair(d, nv, leaves):
    # returns pair (A,B) sharing skeleton
    if d<=0:
        a,b=random.choice(leaves),random.choice(leaves)
        return a,b
    t=random.randrange(6)
    if t==0: return NAT,NAT
    if t==1:
        a,b=pair(d-1,nv,leaves); return arr(a,b),arr(a,b)  # same, less interesting
    if t==2:
        # arrows with different components
        a1,b1=pair(d-1,nv,leaves); a2,b2=pair(d-1,nv,leaves)
        return arr(a1,a2),arr(b1,b2)
    if t==3:
        a,b=pair(d-1,nv+1,leaves+[b(0)])
        return mu(a),mu(b)
