        a1,b1=pair(d-1,nv,leaves); a2,b2=pair(d-1,nv+1,leaves+[b(0)])
        return allt(a1,a2),allt(b1,b2)
    if t==5:
        l=random.randrange(3)
        a,b=pair(d-1,nv,leaves)
        return lab(l,a),lab(l,b)
    return TOP,TOP

