import random,sys,time
sys.setrecursionlimit(1000000)
random.seed(11)

def gen(k, body):
    T=body
    for i in range(k):
        T=mu(T)
    return T

def leafpair(k):
    # leaves referencing bound vars of k nested mus: index i for i-th enclosing? use b(j)
    def l(): return random.choice([NAT,TOP]+[b(j) for j in range(k)])
    return l(),l()

def pair_body(d,k):
    if d<=0:
        return leafpair(k)
    t=random.randrange(5)
    if t==0: return NAT,NAT
    if t==1:
        a1,b1=pair_body(d-1,k); a2,b2=pair_body(d-1,k)
        return arr(a1,a2),arr(b1,b2)
    if t==2:
        # add binder: shift leaves? we ignore shifting; body vars refer as-is; not exact but ok for stress
        a1,b1=pair_body(d-1,k+1)
        return mu(a1),mu(b1)
    if t==3:
        a1,b1=pair_body(d-1,k); a2,b2=pair_body(d-1,k+1)
        return allt(a1,a2),allt(b1,b2)
    if t==4:
        l=random.randrange(2); a1,b1=pair_body(d-1,k)
        return lab(l,a1),lab(l,b1)
    return leafpair(k)

maxtot=0; worst=None
for trial in range(3000):
    k=random.randrange(0,6)
    d=random.randrange(1,6)
    a1,b1=pair_body(d,k)
    # wrap in k mus to match bound vars: our leaves use b(j) for j<k; under k binders, b(0) is innermost.
    A=gen(k,a1); B=gen(k,b1)
    # ensure WF-ish? check wf_dec
    if not (wf_env([]) and wf_dec([],A)): continue
    tr=[]
    t0=time.time()
    try:
        r=sub_dec([],A,B,trace=tr); dt=time.time()-t0
    except RecursionError:
        print("RECURSION ERROR",k,d); print(A); print(B); break
    md=max((x[0] for x in tr),default=0)
    if md>maxtot: maxtot=md; worst=(A,B,dt)
    if depth_exceeded[0]: print("EXCEEDED",trial,k,d); print(A); print(B); break
    if dt>2: print("slow",trial,dt); print(A); print(B)
print("maxdepth",maxtot,"worsttime",worst[2] if worst else None)
if worst: print(worst[0]); print(worst[1])
