        a1,b1=pair_body(d-1,k); a2,b2=pair_body(d-1,k); return arr(a1,a2),arr(b1,b2)
    if t==2:
        a1,b1=pair_body(d-1,k+1); return mu(a1),mu(b1)
    if t==3:
        a1,b1=pair_body(d-1,k); a2,b2=pair_body(d-1,k+1); return allt(a1,a2),allt(b1,b2)
    if t==4:
        l=random.randrange(2); a1,b1=pair_body(d-1,k); return lab(l,a1),lab(l,b1)
    return leafpair(k)

maxtot=0; worst=None
