    k=random.randrange(0,6); d=random.randrange(1,6)
    a1,b1=pair_body(d,k)
    A=gen(k,a1); B=gen(k,b1)
    if not wf_dec([],A): continue
    tr=[]; t0=time.time()
    signal.alarm(2)
    try:
        r=sub_dec([],A,B,trace=tr); dt=time.time()-t0
        signal.alarm(0)
    except TO:
        print("TIMEOUT",trial,"k",k,"d",d); print("A=",A); print("B=",B); break
    except RecursionError:
        print("RECURSION ERROR",k,d); print(A); print(B); break
    md=max((x[0] for x in tr),default=0)
    if md>maxtot: maxtot=md; worst=(A,B,dt)
    if depth_exceeded[0]: print("EXCEEDED",trial,k,d); print(A); print(B); break
    if dt>0.5: print("slow",trial,dt); print(A); print(B)
print("done maxdepth",maxtot,"worsttime",worst[2] if worst else None)
