import random,sys,time
sys.setrecursionlimit(1000000)
NAT=('nat',); TOP=('top',); NIL=('nil',)
def b(i): return ('b',i)
def v(x): return ('v',x)
def arr(a,c): return ('arr',a,c)
def allt(a,c): return ('all',a,c)
def mu(a): return ('mu',a)
def lab(l,a): return ('lab',l,a)
def cons(i,a,c): return ('cons',i,a,c)
def open_tt_rec(K,U,T):
    t=T[0]
    if t in ('nat','top','nil'): return T
    if t=='b': return U if K==T[1] else T
    if t=='v': return T
    if t=='arr': return arr(open_tt_rec(K,U,T[1]),open_tt_rec(K,U,T[2]))
    if t=='all': return allt(open_tt_rec(K,U,T[1]),open_tt_rec(K+1,U,T[2]))
    if t=='mu': return mu(open_tt_rec(K+1,U,T[1]))
    if t=='lab': return lab(T[1],open_tt_rec(K,U,T[2]))
    if t=='cons': return cons(T[1],open_tt_rec(K,U,T[2]),open_tt_rec(K,U,T[3]))
def open_tt(T,U): return open_tt_rec(0,U,T)
def fv_tt(T):
    t=T[0]
    if t in ('nat','top','nil','b'): return frozenset()
    if t=='v': return frozenset({T[1]})
    if t=='arr' or t=='all': return fv_tt(T[1])|fv_tt(T[2])
    if t=='mu': return fv_tt(T[1])
    if t=='lab': return fv_tt(T[2])
    if t=='cons': return fv_tt(T[2])|fv_tt(T[3])
def fl_tt(T):
    t=T[0]
    if t in ('nat','top','nil','b','v'): return frozenset()
    if t=='arr' or t=='all': return fl_tt(T[1])|fl_tt(T[2])
    if t=='mu': return fl_tt(T[1])
    if t=='lab': return frozenset({T[1]})|fl_tt(T[2])
    if t=='cons': return frozenset({T[1]})|fl_tt(T[2])|fl_tt(T[3])
def collectLabel(T):
    return frozenset({T[1]})|collectLabel(T[3]) if T[0]=='cons' else frozenset()
def Tlookup(i,T):
    if T[0]=='cons': return T[2] if T[1]==i else Tlookup(i,T[3])
    return None
def rt_type(T): return T[0] in ('nil','cons')
def atoms_of(T): return fv_tt(T)|fl_tt(T)
def atoms_env(E):
    s=set()
    for (x,k,T) in E: s|={x}|atoms_of(T)
    return s
def fresh(avoid):
    x=0
    while x in avoid: x+=1
    return x

wfcache={}
wfecache={}
def wf_env(E):
    key=tuple(E)
    if key in wfecache: return wfecache[key]
    if not E: r=True
    else:
        (x,k,T)=E[0]; rest=E[1:]
        r = (x not in {y for (y,_,_) in rest}) and wf_env(rest) and wf_dec(rest,T)
    wfecache[key]=r; return r
def wf_dec(E,T):
    key=(tuple(E),T)
    if key in wfcache: return wfcache[key]
    t=T[0]
    if t in ('top','nat','nil'): r=True
    elif t=='v': r=any(y==T[1] and k=='sub' for (y,k,_) in E)
    elif t=='arr': r=wf_dec(E,T[1]) and wf_dec(E,T[2])
    elif t=='lab': r=wf_dec(E,T[2])
    elif t=='cons': r=wf_dec(E,T[2]) and wf_dec(E,T[3]) and rt_type(T[3]) and (T[1] not in collectLabel(T[3]))
    elif t=='all':
        if not wf_dec(E,T[1]): r=False
        else:
            X=fresh(atoms_env(E)|atoms_of(T[1])|atoms_of(T[2]))
            r=wf_dec([(X,'sub',T[1])]+E, open_tt(T[2],v(X)))
    elif t=='mu':
        X=fresh(atoms_env(E)|atoms_of(T[1]))
        E2=[(X,'sub',TOP)]+E
        P=open_tt(T[1],v(X)); Q=open_tt(T[1],lab(X,P))
        r=wf_dec(E2,P) and wf_dec(E2,Q)
    else: r=False
    wfcache[key]=r; return r
def binds(E,X):
    for (y,k,T) in E:
        if y==X: return (k,T)
    return None

MAXD=100000
depth_exceeded=[False]
calls=[0]

def sub_dec(E,A,B,depth=0):
    calls[0]+=1
    if depth>MAXD:
        depth_exceeded[0]=True; return False
    if not wf_env(E): return False
    if B==TOP: return wf_dec(E,A)
    t=A[0]
    if t=='nat': return B==NAT
    if t=='top': return False
    if t=='v':
        X=A[1]
        if B==A and wf_dec(E,A): return True
        bb=binds(E,X)
        if bb is not None and bb[0]=='sub': return sub_dec(E,bb[1],B,depth+1)
        return False
    if t=='arr':
        if B[0]!='arr': return False
        return sub_dec(E,B[1],A[1],depth+1) and sub_dec(E,A[2],B[2],depth+1)
    if t=='all':
        if B[0]!='all': return False
        S1,T1=A[1],A[2]; S2,T2=B[1],B[2]
        if not (sub_dec(E,S1,S2,depth+1) and sub_dec(E,S2,S1,depth+1)): return False
        X=fresh(atoms_env(E)|atoms_of(A)|atoms_of(B))
        return sub_dec([(X,'sub',S2)]+E, open_tt(T1,v(X)), open_tt(T2,v(X)),depth+1)
    if t=='mu':
        if B[0]!='mu': return False
        A1,A2=A[1],B[1]
        X=fresh(atoms_env(E)|atoms_of(A)|atoms_of(B))
        E2=[(X,'sub',TOP)]+E
        P1=open_tt(A1,v(X)); P2=open_tt(A2,v(X))
        U1=open_tt(A1,lab(X,P1)); U2=open_tt(A2,lab(X,P2))
        if not (wf_dec(E2,U1) and wf_dec(E2,U2)): return False
        return sub_dec(E2,U1,U2,depth+1)
    if t=='lab':
        if B[0]!='lab' or A[1]!=B[1]: return False
        return sub_dec(E,A[2],B[2],depth+1)
    if t=='cons':
        if B[0]!='cons': return False
        if not (rt_type(A) and rt_type(B)): return False
        if not collectLabel(B)<=collectLabel(A): return False
        if not (wf_dec(E,A) and wf_dec(E,B)): return False
        for i in collectLabel(B):
            t1=Tlookup(i,A); t2=Tlookup(i,B)
            if t1 is not None and t2 is not None and not sub_dec(E,t1,t2,depth+1): return False
        return True
    if t=='nil': return B[0]=='nil'
    return False

def gen(k, body):
    T=body
    for i in range(k): T=mu(T)
    return T
def leafpair(k):
    def l(): return random.choice([NAT,TOP]+[b(j) for j in range(k)])
    return l(),l()
def pair_body(d,k):
    if d<=0: return leafpair(k)
    t=random.randrange(5)
    if t==0: return NAT,NAT
    if t==1:
        a1,b1=pair_body(d-1,k); a2,b2=pair_body(d-1,k); return arr(a1,a2),arr(b1,b2)
    if t==2:
        a1,b1=pair_body(d-1,k+1); return mu(a1),mu(b1)
    if t==3:
        a1,b1=pair_body(d-1,k); a2,b2=pair_body(d-1,k+1); return allt(a1,a2),allt(b1,b2)
    if t==4:
        l=random.randrange(2); a1,b1=pair_body(d-1,k); return lab(l,a1),lab(l,b1)
    return leafpair(k)

random.seed(11)
maxtot=0; worst=None; maxcalls=0
