    if depth_exceeded[0]: print("EXCEEDED",trial,k,d); print(A); print(B); break
    maxcalls=max(maxcalls,calls[0])
    if dt>maxtot: maxtot=dt; worst=(A,B,calls[0])
    if dt>3: print("slow",trial,dt,calls[0]); print(A); print(B)
print("elapsed",time.time()-t_start,"maxtime",maxtot,"maxcalls",maxcalls)
if worst: print(worst[0]); print(worst[1])
