import random,sys
random.seed(33)
def gen(d, nb):
    if d<=0:
        return random.choice([NAT,TOP]+([b(random.randrange(nb))] if nb>0 else []))
    t=random.randrange(6)
    if t==0: return NAT
    if t==1: return arr(gen(d-1,nb),gen(d-1,nb))
    if t==2: return allt(gen(d-1,nb),gen(d-1,nb+1))
    if t==3: return mu(gen(d-1,nb+1))
    if t==4: return lab(random.randrange(2),gen(d-1,nb))
    if t==5: return cons(random.randrange(2),gen(d-1,nb),gen(d-1,nb))
    return TOP
# depth of memoized recursion (longest chain), with cycle cut
def depthR(E,A,B):
    done={}; stack=set(); best=[0]
    def go(E,A,B,d):
        best[0]=max(best[0],d)
        key=(tuple(E),A,B)
        if key in done: return done[key]
        if key in stack: return False
        stack.add(key)
        r=go2(E,A,B,d+1)
        stack.discard(key); done[key]=r; return r
    def go2(E,A,B,d):
        if not wf_env(E): return False
        if B==TOP: return wf_dec(E,A)
        t=A[0]
        if t=='nat': return B==NAT
        if t=='top': return False
        if t=='v':
            X=A[1]
            if B==A and wf_dec(E,A): return True
            bb=binds(E,X)
            if bb is not None and bb[0]=='sub': return go(E,bb[1],B,d)
            return False
        if t=='arr':
            if B[0]!='arr': return False
            return go(E,B[1],A[1],d) and go(E,A[2],B[2],d)
        if t=='all':
            if B[0]!='all': return False
            S1,T1=A[1],A[2]; S2,T2=B[1],B[2]
            if not (go(E,S1,S2,d) and go(E,S2,S1,d)): return False
            X=fresh(atoms_env(E)|atoms_of(A)|atoms_of(B))
            return go([(X,'sub',S2)]+E, open_tt(T1,v(X)), open_tt(T2,v(X)),d)
        if t=='mu':
            if B[0]!='mu': return False
            A1,A2=A[1],B[1]
            X=fresh(atoms_env(E)|atoms_of(A)|atoms_of(B))
            E2=[(X,'sub',TOP)]+E
            if not (wf_dec(E2, open_tt(A1,v(X))) and wf_dec(E2, open_tt(A2,v(X)))): return False
            return go(E2, open_tt(A1,v(X)), open_tt(A2,v(X)),d)
        if t=='lab':
            if B[0]!='lab' or A[1]!=B[1]: return False
            return go(E,A[2],B[2],d)
        if t=='cons':
            if B[0]!='cons': return False
            if not (rt_type(A) and rt_type(B)): return False
            if not collectLabel(B)<=collectLabel(A): return False
            if not (wf_dec(E,A) and wf_dec(E,B)): return False
            for i in collectLabel(B):
                t1=Tlookup(i,A); t2=Tlookup(i,B)
                if t1 is not None and t2 is not None and not go(E,t1,t2,d): return False
            return True
        if t=='nil': return B[0]=='nil'
        return False
    r=go(E,A,B,0); return r,best[0]
mx=(0,None); worstratio=0
