exec(open('/tmp/work/reduced.py').read().split("def rnd(")[0])
import random,sys
sys.setrecursionlimit(1000000)
random.seed(505)

def fvlist(T):
    # list of fvar occurrences
    t=T[0]
    if t=='v': return [T[1]]
    if t in ('nat','top','nil','b','mu','lab','cons','arr','all'):
        if t in ('nat','top','nil','b'): return []
        if t=='mu' or t=='lab': return fvlist(T[-1] if t=='lab' else T[1])
        if t in ('arr','all'): return fvlist(T[1])+fvlist(T[2])
        if t=='cons': return fvlist(T[2])+fvlist(T[3])
    return []

def EW(E,T,memo):
    # raw size + sum over fvar occurrences w(X); bvars raw 1
    key=(tuple(E),T)
    if key in memo: return memo[key]
    t=T[0]
    if t=='v':
        r=w_of(E,T[1],memo); memo[key]=r; return r
    if t in ('nat','top','nil','b'): r=1
    elif t=='arr': r=1+EW(E,T[1],memo)+EW(E,T[2],memo)
    elif t=='all': r=1+EW(E,T[1],memo)+EW(E,T[2],memo)
    elif t=='mu': r=1+EW(E,T[1],memo)
    elif t=='lab': r=1+EW(E,T[2],memo)
    elif t=='cons': r=1+EW(E,T[2],memo)+EW(E,T[3],memo)
    else: r=1
    memo[key]=r; return r

def w_of(E,X,memo):
    bb=binds(E,X)
    if bb is None or bb[0]!='sub':
        # unbound: weight 1
        return 1
    return EW(E,bb[1],memo)

# Wsum pair-sensitive with ctx list of bvar weights (index0 = innermost/current binder)
def Wpair(E,ctx,A,B,memo):
    tA,tB=A[0],B[0]
    if tA=='mu' and tB=='mu':
        return 2 + Wpair(E,[1]+ctx,A[1],B[1],memo)
    if tA=='all' and tB=='all':
        S1,T1,S2,T2=A[1],A[2],B[1],B[2]
        b=EW(E,S2,memo)  # weight of fresh X bound to S2
        return 2 + Wpair(E,ctx,S1,S2,memo)+Wpair(E,ctx,S2,S1,memo)+Wpair(E,[b]+ctx,T1,T2,memo)
    if tA=='arr' and tB=='arr':
        return 2 + Wpair(E,ctx,B[1],A[1],memo)+Wpair(E,ctx,A[2],B[2],memo)
    if tA=='lab' and tB=='lab' and A[1]==B[1]:
        return 2 + Wpair(E,ctx,A[2],B[2],memo)
    if tA=='cons' and tB=='cons':
        # approximate: match labels, recurse on lookup pairs + tails
        A1,B1=A,B
        tot=0
        for i in collectLabel(B1):
            ta=Tlookup(i,A1); tb=Tlookup(i,B1)
            if ta is not None and tb is not None: tot+=Wpair(E,ctx,ta,tb,memo)
        return 2+tot
    if tA=='nil' and tB=='nil': return 2
    # fvar cases
    if tA=='v':
        return w_of(E,A[1],memo) + Wsingle(E,ctx,B,memo)
    if tB=='v':
