    L=[]
    for T in subterms(A): L.append(weight(T) if weighted else size(T))
    for T in subterms(B): L.append(weight(T) if weighted else size(T))
    return sorted(L,reverse=True)

def mul_lt(M,N):
    # M <mul N : M can be obtained from N by replacing elements by finitely many strictly smaller ones.
    # Greedy characterization: sort descending; pair by index; need m_i <= n_i for i<|M| and
    # either |M|<|N| or some strict.
    M=sorted(M,reverse=True); N=sorted(N,reverse=True)
    # pad M with nothing; check dominance of M over a submultiset of N with strict somewhere/removal
    # Try matching each m to some n>=m injectively.
    used=[False]*len(N)
    strict=False
    for m in M:
        found=False
        for j,n in enumerate(N):
            if not used[j] and n>=m:
                used[j]=True; found=True
                if n>m: strict=True
                break
        if not found: return False
    # need at least one unused N or a strict match
    if strict or any(not u for u in used): return True
    return False

