exec(open('/tmp/work/core.py').read())
import random,sys
sys.setrecursionlimit(1000000)

def we(T):
    t=T[0]
    if t in ('nat','top','b','v','nil'): return 1
    if t=='lab': return 1
    if t in ('arr','all','cons'): return 1+we(T[1])+we(T[2]) if t!='cons' else 1+we(T[2])+we(T[3])
    if t=='mu': return 1+we(T[1])
    return 1

def fv(T):
    t=T[0]
    if t=='v': return {T[1]}
    if t in ('nat','top','b','nil'): return set()
    if t in ('arr','all'): return fv(T[1])|fv(T[2])
    if t=='mu': return fv(T[1])
    if t=='lab': return fv(T[2])
    return fv(T[2])|fv(T[3])

def w(E,X):
    # lookup binding, recursive expansion weight; assumes well-founded env but define defensively
    bb=binds(E,X)
    if bb is None or bb[0]!='sub': return 1
    U=bb[1]
    return we(U) + sum(w(E,Y) for Y in fv(U))

def M(E,A,B):
    return we(A)+we(B)+sum(w(E,X) for X in (fv(A)|fv(B)))

def pos(E,X):
    p=0
    for (y,c,T) in E:
        if y==X: return p
        p+=1
    return p
def rank(E,A):
    if A[0]=='v':
        bb=binds(E,A[1])
        if bb is not None and bb[0]=='sub':
            p=pos(E,A[1])
            return 1 + (len(E)-p)
    return 0

# enumerate the original-sub rule children with the exact child envs
def children(E,A,B):
    out=[]
    if B==TOP: return out
    t=A[0]
    if t=='nat': return out
    if t=='top': return out
    if t=='v':
        X=A[1]
        if B==A: return out
        bb=binds(E,X)
        if bb is not None and bb[0]=='sub': out.append((E,bb[1],B,'trans'))
        return out
    if t=='arr':
        if B[0]=='arr': out+=[(E,B[1],A[1],'arr1'),(E,A[2],B[2],'arr2')]
        return out
    if t=='all':
        if B[0]=='all':
            S1,T1=A[1],A[2]; S2,T2=B[1],B[2]
            X=fresh(atoms_env(E)|atoms_of(A)|atoms_of(B))
            out+=[(E,S1,S2,'all1'),(E,S2,S1,'all2'),
                  ([(X,'sub',S2)]+E,open_tt(T1,v(X)),open_tt(T2,v(X)),'all3')]
        return out
    if t=='mu':
        if B[0]=='mu':
            A1,A2=A[1],B[1]; X=fresh(atoms_env(E)|atoms_of(A)|atoms_of(B))
            E2=[(X,'sub',TOP)]+E
            P1=open_tt(A1,v(X)); P2=open_tt(A2,v(X))
            U1=open_tt(A1,lab(X,P1)); U2=open_tt(A2,lab(X,P2))
            out.append((E2,U1,U2,'muL'))
        return out
    if t=='lab':
        if B[0]=='lab' and A[1]==B[1]: out.append((E,A[2],B[2],'lab'))
        return out
    if t=='cons':
        if B[0]=='cons':
            for i in collectLabel(B):
                t1=Tlookup(i,A); t2=Tlookup(i,B)
                if t1 is not None and t2 is not None: out.append((E,t1,t2,'rcd'))
        return out
    return out

def genE(d,fvs):
    if d<=0:
        ch=random.randrange(4)
        if ch==0: return NAT
        if ch==1 and fvs: return v(random.choice(fvs))
        if ch==2: return TOP
        return NAT
    t=random.randrange(7)
    if t==0: return NAT
    if t<=2: return arr(genE(d-1,fvs),genE(d-1,fvs))
    if t==3: return allt(genE(d-1,fvs),genE(d-1,fvs))
    if t==4: return mu(genE(d-1,fvs))
    if t==5: return lab(random.randrange(2),genE(d-1,fvs))
    return cons(random.randrange(2),genE(d-1,fvs),genE(d-1,fvs))

random.seed(2024)
bad=[]; tested=0
for trial in range(8000):
    E=[]; dom=[]
    for i in range(random.randrange(0,3)):
        x=3000000+trial*7+i
        T=genE(random.randrange(1,3),dom)
        if not wf_dec(E,T): continue
        E=[(x,'sub',T)]+E; dom+=[x]
    A=genE(random.randrange(1,4),dom); B=genE(random.randrange(1,4),dom)
    if not (wf_dec(E,A) and wf_dec(E,B)): continue
    tested+=1
    mp=M(E,A,B); rp=rank(E,A)
    for (E2,A2,B2,rule) in children(E,A,B):
        mc=M(E2,A2,B2); rc=rank(E2,A2)
        ok = (mc < mp) or (mc==mp and rc<rp)
        if not ok:
            bad.append((rule,mp,rp,mc,rc,E,A,B,A2,B2)); break
    if bad: break
print("tested",tested,"violations",len(bad))
if bad:
