# ---------------- bvar-aware random type generator ----------------
def gen_scoped(d, depth, fvs, labels=(0,1), allow_label=True, allow_rcd=True,
               pnat=0.16, ptop=0.18, pv=0.14, parr=0.24, pall=0.10, pmu=0.12,
               plab=0.06, prcd=0.06):
    """depth = number of enclosing type binders; free bvars may be b(0..depth-1)."""
    r=random.random(); acc=0.0
    acc+=pnat
    if r<acc: return NAT
    acc+=ptop
    if r<acc: return TOP
    acc+=pv
    if r<acc and fvs: return v(random.choice(fvs))
    # fall through to compound
    if d<=0:
        if depth>0 and random.random()<0.6: return b(random.randrange(depth))
        if fvs and random.random()<0.6: return v(random.choice(fvs))
        return TOP if random.random()<0.5 else NAT
    # compound weights (normalized over remaining)
    choices=[]
    choices.append(('arr',parr))
    choices.append(('all',pall))
    choices.append(('mu',pmu))
    if allow_label: choices.append(('lab',plab))
    if allow_rcd: choices.append(('cons',prcd))
    tot=sum(w for _,w in choices)
    r2=random.random()*tot; acc=0.0; kind='arr'
    for k,w in choices:
        acc+=w
        if r2<acc: kind=k; break
    if kind=='arr':
        return arr(gen_scoped(d-1,depth,fvs,labels,allow_label,allow_rcd,pnat,ptop,pv,parr,pall,pmu,plab,prcd),
                   gen_scoped(d-1,depth,fvs,labels,allow_label,allow_rcd,pnat,ptop,pv,parr,pall,pmu,plab,prcd))
    if kind=='all':
        return allt(gen_scoped(d-1,depth,fvs,labels,allow_label,allow_rcd,pnat,ptop,pv,parr,pall,pmu,plab,prcd),
                    gen_scoped(d-1,depth+1,fvs,labels,allow_label,allow_rcd,pnat,ptop,pv,parr,pall,pmu,plab,prcd))
    if kind=='mu':
        return mu(gen_scoped(d-1,depth+1,fvs,labels,allow_label,allow_rcd,pnat,ptop,pv,parr,pall,pmu,plab,prcd))
    if kind=='lab':
        return lab(random.choice(labels),gen_scoped(d-1,depth,fvs,labels,allow_label,allow_rcd,pnat,ptop,pv,parr,pall,pmu,plab,prcd))
    return cons(random.choice(labels),gen_scoped(d-1,depth,fvs,labels,allow_label,allow_rcd,pnat,ptop,pv,parr,pall,pmu,plab,prcd),
                gen_scoped(d-1,depth,fvs,labels,allow_label,allow_rcd,pnat,ptop,pv,parr,pall,pmu,plab,prcd))

def gen_random_case(d=4, nenv=2, atom_base=1000, **kw):
    E=[]; fvs=[]
    for j in range(nenv):
        X=atom_base+j
        T=gen_scoped(max(1,d-1),0,fvs,**kw)
        if wf_dec(E,T):
            E=[(X,'sub',T)]+E; fvs.append(X)
    if not wf_env(E): return None
    A=gen_scoped(d,0,fvs,**kw); B=gen_scoped(d,0,fvs,**kw)
    if not (wf_dec(E,A) and wf_dec(E,B)): return None
    return E,A,B

def run_comparison(n=500, d=4, nenv=2, seed=1, cap=18, verbose=0, **kw):
    random.seed(seed)
    res={'n':0,'oracle_true':0,'oracle_unknown':0,
         'checked_mismatch':[], 'decl_mismatch':[], 'assumeP_mismatch':[],
         'assumeP2_mismatch':[], 'assumeboth_mismatch':[],
         'checked_exc':0,'decl_exc':0, 'oracle_states':{}}
    t0=time.time(); tried=0
    while res['n']<n and tried<n*30:
        tried+=1
        c=gen_random_case(d,nenv,**kw)
        if c is None: continue
        E,A,B=c
        res['n']+=1
        ov,od,unk=sub_oracle(E,A,B,cap)
        if ov: res['oracle_true']+=1
        if unk: res['oracle_unknown']+=1
        res['oracle_states'][od]=res['oracle_states'].get(od,0)+1
        dr,ds,dexc=decl_search_top(E,A,B,100000)
        if dexc: res['decl_exc']+=1
        cr,cs,cexc=alg_top(E,A,B,200000)
        if cexc: res['checked_exc']+=1
        ap,_,_=assume_mode_top(E,A,B,True)
        ap2,_,_=assume_mode_top(E,A,B,False)
        ab,_,_=assume_both_top(E,A,B)
        # ground truth: if oracle has definite proof => True. if decl no-exc definite => use it.
        truth = True if ov else (dr if dr is not None else ov)
        if cr != truth and not (cexc): res['checked_mismatch'].append((E,A,B,truth,cr,ov,od,unk,dr))
        if dr != ov and not dexc and not unk: res['decl_mismatch'].append((E,A,B,ov,dr,od))
        if ap != truth: res['assumeP_mismatch'].append((E,A,B,truth,ap,ov,od,unk))
        if ap2 != truth: res['assumeP2_mismatch'].append((E,A,B,truth,ap2,ov,od,unk))
        if ab != truth: res['assumeboth_mismatch'].append((E,A,B,truth,ab,ov,od,unk))
        if verbose and res['n']%verbose==0: print('..',res['n'],round(time.time()-t0,2))
        if len(res['assumeP_mismatch'])>20 and len(res['checked_mismatch'])>20: break
    res['time']=time.time()-t0; res['tried']=tried
    return res

def summarize(res, show=3):
    print('cases',res['n'],'tried',res['tried'],'oracle_true',res['oracle_true'],
          'oracle_unknown',res['oracle_unknown'],'time',round(res['time'],2))
    print('oracle depths',dict(sorted(res['oracle_states'].items())))
    print('exc decl',res['decl_exc'],'checked',res['checked_exc'])
    for k in ('checked_mismatch','decl_mismatch','assumeP_mismatch','assumeP2_mismatch','assumeboth_mismatch'):
        v=res[k]; print(k,len(v))
        for x in v[:show]: print('   ',x)

if __name__=='__main__':
