def mutate(T, fvs, depth=0, p_change=0.25, p_top=0.12, p_nat=0.08, p_fv=0.10, p_lab=0.08, p_swap=0.05):
    r=random.random()
    if r<p_top: return TOP
    r-=p_top
    if r<p_nat: return NAT
    r-=p_nat
    if r<p_fv and fvs: return v(random.choice(fvs))
    t=T[0]
    if t in ('nat','top','nil','b','v'):
        return T
    if t=='arr':
        a,b=T[1],T[2]
        if random.random()<p_swap: a,b=b,a
        return arr(mutate(a,fvs,depth,p_change,p_top,p_nat,p_fv,p_lab,p_swap),
                   mutate(b,fvs,depth,p_change,p_top,p_nat,p_fv,p_lab,p_swap))
    if t=='all':
        return allt(mutate(T[1],fvs,depth,p_change,p_top,p_nat,p_fv,p_lab,p_swap),
                    mutate(T[2],fvs,depth,p_change,p_top,p_nat,p_fv,p_lab,p_swap))
    if t=='mu':
        return mu(mutate(T[1],fvs,depth,p_change,p_top,p_nat,p_fv,p_lab,p_swap))
    if t=='lab':
        l=T[1]
        if random.random()<p_lab: l=random.choice([0,1,2])
        return lab(l,mutate(T[2],fvs,depth,p_change,p_top,p_nat,p_fv,p_lab,p_swap))
    # cons
    l=T[1]
    if random.random()<p_lab: l=random.choice([0,1,2])
    return cons(l,mutate(T[2],fvs,depth,p_change,p_top,p_nat,p_fv,p_lab,p_swap),
                mutate(T[3],fvs,depth,p_change,p_top,p_nat,p_fv,p_lab,p_swap))

