    A=gen_scoped(d,0,fvs,**kw)
    if not wf_dec(E,A): return None
    B=mutate(A,fvs)
    if not wf_dec(E,B): return None
    return A,B

def run(n=1000, seed=0, d=5, nenv=3, cap=22, maxsteps=200000, **kw):
    random.seed(seed)
