            if wf_dec(E,T):
                E=[(X,'sub',T)]+E; fvs.append(X)
        if not wf_env(E): continue
        # sometimes generate independent B
        if random.random()<0.5:
            A=gen_scoped(d,0,fvs,**kw); B=gen_scoped(d,0,fvs,**kw)
            if not (wf_dec(E,A) and wf_dec(E,B)): continue
