"""Instrument the checked obligation algorithm and test candidate measures.

The checked algorithm (alg/prove in algs.py) has these recursive call edges:
  trans   : (E, fvar X, B)            -> (E, U, B)                 [binds X (sub U) E]
  lab     : (E, lab X a, lab X b)     -> (E, a, b)       (X not active)
  arrow   : (E, arr A1 A2, arr B1 B2) -> (E, B1, A1), (E, A2, B2)
  all     : (E, all S1 T1, all S2 T2) -> (E,S1,S2), (E,S2,S1), (E2,T1[X],T2[X])
  mu      : (E, mu A1, mu A2)         -> (E2,U1,U2) with X fresh, E2=X:sub TOP++E,
                                          U1=A1[lab X P1], U2=A2[lab X P2],
                                          P1=A1[X], P2=A2[X], Sigma+=X
            then each checked obligation (Eo,C,D) collected for X is discharged by a
            top-level alg call:  (Eo,C,D)   [Sigma still contains X]
  rcd     : (E, R1, R2)               -> (E, lookup i R1, lookup i R2)

We record, for each edge, parent/child states (Sigma, E, A, B, pending) and test
whether candidate measures strictly decrease.
"""
import sys, sys as _sys, random, time
sys.setrecursionlimit(1000000)
exec(open('/workspace/.scratch/agent/core.py').read())

# ---------------- weight functions ----------------
def mk_we(sigma, fvar_mode='unit', mu_coeff=1, env_mode='sum', bind_cache=None):
    """Return we(T).  sigma: frozenset/set of opaque labels.
       fvar_mode: 'unit' -> w(fvar)=1 ; 'binding' -> 1+w(binding type)
       mu_coeff: w(mu T)=1+mu_coeff*w(T)
       env_mode used only for env weight, not here."""
    cache={}
    def we(E,T):
        key=(T, sigma) if fvar_mode=='unit' else (T, sigma, tuple(E))
        if key in cache: return cache[key]
        t=T[0]
        if t in ('nat','top','nil','b'): r=1
        elif t=='v':
            if fvar_mode=='unit': r=1
            elif fvar_mode=='zero': r=0
            else:
                bb=binds(E,T[1])
                r=1
                if bb is not None: r=1+we(E,bb[1])
        elif t=='arr': r=1+we(E,T[1])+we(E,T[2])
        elif t=='all': r=1+we(E,T[1])+we(E,T[2])
        elif t=='mu': r=1+mu_coeff*we(E,T[1])
        elif t=='lab': r=1 if T[1] in sigma else 1+we(E,T[2])
        else: r=1+we(E,T[2])+we(E,T[3])
        cache[key]=r; return r
    return we

def env_weight(E, we, per_binding=1):
    s=0
    for (x,k,T) in E: s+=per_binding+we(E,T)
    return s

def pending_weight(pending, we):
    s=0
    for (Eo,C,D) in pending: s+=we(Eo,C)+we(Eo,D)
    return s

# ---------------- instrumented checked algorithm ----------------
class EDGES: pass
E_REC=[]

def instrument(E,A,B,Sigma=None):
    """Run checked algorithm, record every recursive edge as a dict."""
    global E_REC
    E_REC=[]
    err=[None]
    def prove(E,A,B,active,pending_sink):
        # returns (ok, needs); needs dict label -> list of (Eo,C,D)
        if B==TOP and wf_dec(E,A): return True,{}
        if A==NAT and B==NAT and wf_env(E): return True,{}
        if A[0]=='v' and A==B and wf_env(E) and wf_dec(E,A): return True,{}
        if A[0]=='v':
            bb=binds(E,A[1])
            if bb is not None and bb[0]=='sub':
                E_REC.append(dict(kind='trans',sig=set(Sigma),E=E,A=A,B=B,
                                  csig=set(Sigma),cE=E,cA=bb[1],cB=B,pend=list(pending_sink)))
                return prove(E,bb[1],B,active,pending_sink)
            return False,{}
        if A[0]=='lab' and B[0]=='lab' and A[1]==B[1]:
            X=A[1]
            if X in active:
                ob=(E,A[2],B[2])
                E_REC.append(dict(kind='assert',sig=set(Sigma),E=E,A=A,B=B,
                                  csig=set(Sigma),cE=E,cA=A[2],cB=B[2],ob=ob,
                                  pend=list(pending_sink),myob=ob))
                return True,{X:[ob]}
            E_REC.append(dict(kind='lab',sig=set(Sigma),E=E,A=A,B=B,
                              csig=set(Sigma),cE=E,cA=A[2],cB=B[2],pend=list(pending_sink)))
            return prove(E,A[2],B[2],active,pending_sink)
        if A[0]=='arr' and B[0]=='arr':
            E_REC.append(dict(kind='arrow',sig=set(Sigma),E=E,A=A,B=B,
                              csig=set(Sigma),cE=E,cA=B[1],cB=A[1],pend=list(pending_sink)))
            ok1,n1=prove(E,B[1],A[1],active,pending_sink)
            if not ok1: return False,{}
            E_REC.append(dict(kind='arrow',sig=set(Sigma),E=E,A=A,B=B,
                              csig=set(Sigma),cE=E,cA=A[2],cB=B[2],pend=list(pending_sink)))
            ok2,n2=prove(E,A[2],B[2],active,pending_sink)
            if not ok2: return False,{}
            return True,merge(n1,n2)
        if A[0]=='all' and B[0]=='all':
            S1,T1=A[1],A[2]; S2,T2=B[1],B[2]
            E_REC.append(dict(kind='all',sig=set(Sigma),E=E,A=A,B=B,
                              csig=set(Sigma),cE=E,cA=S1,cB=S2,pend=list(pending_sink)))
            ok,n1=prove(E,S1,S2,active,pending_sink)
            if not ok: return False,{}
            E_REC.append(dict(kind='all',sig=set(Sigma),E=E,A=A,B=B,
                              csig=set(Sigma),cE=E,cA=S2,cB=S1,pend=list(pending_sink)))
            ok,n2=prove(E,S2,S1,active,pending_sink)
            if not ok: return False,{}
            X=fresh(atoms_env(E)|atoms_of(A)|atoms_of(B))
            E2=[(X,'sub',S2)]+E
            E_REC.append(dict(kind='allbody',sig=set(Sigma),E=E,A=A,B=B,
                              csig=set(Sigma),cE=E2,cA=open_tt(T1,v(X)),cB=open_tt(T2,v(X)),
                              pend=list(pending_sink),newbound=X))
            ok,n3=prove(E2,open_tt(T1,v(X)),open_tt(T2,v(X)),active,pending_sink)
            if not ok: return False,{}
            return True,merge(merge(n1,n2),n3)
        if A[0]=='mu' and B[0]=='mu':
            A1,A2=A[1],B[1]
            if not (wf_dec(E,A) and wf_dec(E,B)): return False,{}
            X=fresh(atoms_env(E)|atoms_of(A)|atoms_of(B))
            E2=[(X,'sub',TOP)]+E
            P1=open_tt(A1,v(X)); P2=open_tt(A2,v(X))
            U1=open_tt(A1,lab(X,P1)); U2=open_tt(A2,lab(X,P2))
            if not (wf_dec(E2,P1) and wf_dec(E2,P2)): return False,{}
            Sigma.add(X)
            E_REC.append(dict(kind='mu',sig=set(Sigma),E=E,A=A,B=B,
                              csig=set(Sigma),cE=E2,cA=U1,cB=U2,pend=list(pending_sink),
                              X=X,P1=P1,P2=P2))
            active2=dict(active); active2[X]=(P1,P2)
            ok,needs=prove(E2,U1,U2,active2,pending_sink)
            if not ok:
                Sigma.discard(X); return False,{}
            mine=needs.pop(X,[])
            # discharge obligations for X, one at a time, recording edges
            seen=set(); oblig=[]
            for o in mine:
                kk=(tuple(o[0]),o[1],o[2])
                if kk in seen: continue
                seen.add(kk); oblig.append(o)
            # pending frame: the remaining outstanding obligations
            work=list(oblig)
            while work:
                o=work.pop(0)
                (Eo,C,D)=o
                pend_all=list(work)
                E_REC.append(dict(kind='oblig',sig=set(Sigma),E=E,A=A,B=B,
                                  csig=set(Sigma),cE=Eo,cA=C,cB=D,
                                  pend=pend_all, X=X, P1=P1,P2=P2,
                                  muE=E,A0=A,B0=B,E2=E2,U1=U1,U2=U2))
                ok2=alg(Eo,C,D)
                if not ok2:
                    Sigma.discard(X); return False,{}
            Sigma.discard(X)
            return True,needs
        if rt_type(A) and rt_type(B):
            if not (wf_env(E) and collectLabel(B)<=collectLabel(A)
                    and wf_dec(E,A) and wf_dec(E,B)): return False,{}
            needs={}
            for i in collectLabel(B):
                t1=Tlookup(i,A); t2=Tlookup(i,B)
                if t1 is None or t2 is None: continue
                E_REC.append(dict(kind='rcd',sig=set(Sigma),E=E,A=A,B=B,
                                  csig=set(Sigma),cE=E,cA=t1,cB=t2,pend=list(pending_sink)))
                ok,nn=prove(E,t1,t2,active,pending_sink)
                if not ok: return False,{}
                needs=merge(needs,nn)
            return True,needs
        return False,{}
    def alg(E,A,B):
        ok,needs=prove(E,A,B,{},[])
        return ok and not needs

    if Sigma is None: Sigma=set()
    r=alg(E,A,B)
    return r,E_REC

def merge(n1,n2):
    if not n1: return dict(n2)
    out={k:list(v) for k,v in n1.items()}
    for k,v in n2.items(): out.setdefault(k,[]).extend(v)
    return out

# ---------------- measure evaluation ----------------
def state_measure(st, params):
    Sig=st['sig']; E=st['E']; A=st['A']; B=st['B']; pending=st.get('pend',[])
    we=mk_we(Sig,fvar_mode=params['fvar'],mu_coeff=params['mu'])
    base=we(E,A)+we(E,B)
    if params.get('envw',0):
        base+=params['envw']*env_weight(E,we,params.get('per_binding',1))
    if params.get('pendw',0):
        base+=params['pendw']*pending_weight(pending,we)
    if params.get('npend',0):
        base+=params['npend']*len(pending)
    return base

def child_state(e):
    return dict(sig=e['csig'],E=e['cE'],A=e['cA'],B=e['cB'],pend=e.get('pend',[]))

def parent_state(e):
    return dict(sig=e['sig'],E=e['E'],A=e['A'],B=e['B'],pend=e.get('pend',[]))

def check_measures(cases, params, verbose_examples=2):
    """For each case, run instrumented algorithm and test decrease on all edges."""
    viol={}
    tot={}
    for (E,A,B) in cases:
        r,edges=instrument(E,A,B,set())
        for e in edges:
            k=e['kind']
            if k=='assert': continue
            tot[k]=tot.get(k,0)+1
            pm=state_measure(parent_state(e),params)
            cm=state_measure(child_state(e),params)
            if not (cm<pm):
                viol.setdefault(k,[]).append((e,pm,cm))
    return tot,viol

def show(tot,viol,name,maxex=3):
    print('---',name)
    for k in sorted(tot):
        v=viol.get(k,[])
        print('  %-8s edges %7d violations %7d'%(k,tot[k],len(v)))
        for (e,pm,cm) in v[:maxex]:
            print('      ex parent',pm,'child',cm,'E',e['E'],'A',e['A'],'B',e['B'],'->',e['cE'],e['cA'],e['cB'])

