"""Focused test: does resolve preprocessing keep M decreasing?

Records, for the checked algorithm, a consumed-fvar set D on every call path.
D starts empty; at trans X -> U we add X to D.  The corrected measure is
    M(S,E,D,A,B) = we_S(A) + we_S(B) + EW_S(E \\ D)
where EW sums we of binding types for bindings whose variable is NOT in D.
The old measure is M with D permanently empty.
"""
import sys, random, time
sys.setrecursionlimit(1000000)
exec(open('/workspace/.scratch/agent/core.py').read())

EDGES=[]

def we(S,T):
    t=T[0]
    if t in ('nat','top','nil','b','v'): return 1
    if t in ('arr','all'): return 1+we(S,T[1])+we(S,T[2])
    if t=='mu': return 1+we(S,T[1])
    if t=='lab': return 1 if T[1] in S else 1+we(S,T[2])
    return 1+we(S,T[2])+we(S,T[3])

def EW(S,E,D):
    s=0
    for (x,k,T) in E:
        if x not in D: s+=we(S,T)
    return s

def M(S,E,D,A,B): return we(S,A)+we(S,B)+EW(S,E,D)

def merge(n1,n2):
    if not n1: return dict(n2)
    out={k:list(v) for k,v in n1.items()}
    for k,v in n2.items(): out.setdefault(k,[]).extend(v)
    return out

def instrument(E,A,B):
    global EDGES
    EDGES=[]
    Sig=set()
    def prove(E,A,B,active,D):
        if B==TOP and wf_dec(E,A): return True,{}
        if A==NAT and B==NAT and wf_env(E): return True,{}
        if A[0]=='v' and A==B and wf_env(E) and wf_dec(E,A): return True,{}
        if A[0]=='v':
            bb=binds(E,A[1])
            if bb is not None and bb[0]=='sub':
                D2=frozenset(set(D)|{A[1]})
                EDGES.append(('trans',Sig,E,D,A,B,E,D2,bb[1],B))
                return prove(E,bb[1],B,active,D2)
            return False,{}
        if A[0]=='lab' and B[0]=='lab' and A[1]==B[1]:
            X=A[1]
            if X in active:
                EDGES.append(('assert',Sig,E,D,A,B,E,D,A[2],B[2]))
                return True,{X:[(E,A[2],B[2])]}
            EDGES.append(('lab',Sig,E,D,A,B,E,D,A[2],B[2]))
            return prove(E,A[2],B[2],active,D)
        if A[0]=='arr' and B[0]=='arr':
            EDGES.append(('arrow',Sig,E,D,A,B,E,D,B[1],A[1]))
            ok,n1=prove(E,B[1],A[1],active,D)
            if not ok: return False,{}
            EDGES.append(('arrow',Sig,E,D,A,B,E,D,A[2],B[2]))
            ok,n2=prove(E,A[2],B[2],active,D)
            if not ok: return False,{}
            return True,merge(n1,n2)
        if A[0]=='all' and B[0]=='all':
            S1,T1=A[1],A[2]; S2,T2=B[1],B[2]
            EDGES.append(('all',Sig,E,D,A,B,E,D,S1,S2))
            ok,n1=prove(E,S1,S2,active,D)
            if not ok: return False,{}
            EDGES.append(('all',Sig,E,D,A,B,E,D,S2,S1))
            ok,n2=prove(E,S2,S1,active,D)
            if not ok: return False,{}
            X=fresh(atoms_env(E)|atoms_of(A)|atoms_of(B))
            E2=[(X,'sub',S2)]+E
            EDGES.append(('allbody',Sig,E,D,A,B,E2,D,open_tt(T1,v(X)),open_tt(T2,v(X))))
            ok,n3=prove(E2,open_tt(T1,v(X)),open_tt(T2,v(X)),active,D)
            if not ok: return False,{}
            return True,merge(merge(n1,n2),n3)
        if A[0]=='mu' and B[0]=='mu':
            A1,A2=A[1],B[1]
            if not (wf_dec(E,A) and wf_dec(E,B)): return False,{}
            X=fresh(atoms_env(E)|atoms_of(A)|atoms_of(B))
            E2=[(X,'sub',TOP)]+E
            P1=open_tt(A1,v(X)); P2=open_tt(A2,v(X))
            U1=open_tt(A1,lab(X,P1)); U2=open_tt(A2,lab(X,P2))
            if not (wf_dec(E2,P1) and wf_dec(E2,P2)): return False,{}
            Sig.add(X)
            EDGES.append(('mu',Sig,E,D,A,B,E2,D,U1,U2,X,P1,P2,E2))
            active2=dict(active); active2[X]=(P1,P2)
            ok,needs=prove(E2,U1,U2,active2,D)
            if not ok:
                Sig.discard(X); return False,{}
            mine=needs.pop(X,[]); seen=set(); oblig=[]
            for o in mine:
                kk=(tuple(o[0]),o[1],o[2])
                if kk in seen: continue
                seen.add(kk); oblig.append(o)
            for o in oblig:
                Eo,C,Dd=o
                # obligation call is a child of the mu invocation; inherit Dframe
                EDGES.append(('oblig',Sig,E,D,A,B,Eo,D,C,Dd,X,P1,P2))
                ok2=alg(Eo,C,Dd)
                if not ok2:
                    Sig.discard(X); return False,{}
            Sig.discard(X)
            return True,needs
        if rt_type(A) and rt_type(B):
            if not (wf_env(E) and collectLabel(B)<=collectLabel(A)
                    and wf_dec(E,A) and wf_dec(E,B)): return False,{}
            needs={}
            for i in collectLabel(B):
                t1=Tlookup(i,A); t2=Tlookup(i,B)
                if t1 is None or t2 is None: continue
                EDGES.append(('rcd',Sig,E,D,A,B,E,D,t1,t2))
                ok,nn=prove(E,t1,t2,active,D)
                if not ok: return False,{}
                needs=merge(needs,nn)
            return True,needs
        return False,{}
    def alg(E,A,B):
        ok,needs=prove(E,A,B,{},frozenset())
        return ok and not needs
    return alg(E,A,B),EDGES,Sig

def check(cases):
    tot={}; bad={}; badold={}
    for (E,A,B) in cases:
        r,edges,_=instrument(E,A,B)
        for e in edges:
            k=e[0]
            if k=='assert': continue
            S=e[1]; Ep=e[2]; Dp=e[3]; Ap=e[4]; Bp=e[5]
