"""Occurrence-token termination measure for the checked sub algorithm.

Token ranks are *remaining environment length from the head*:
    rank_E(X) = len(E) - position_E(X)      (head position 0)
so older bindings get SMALLER ranks.  Prepending a fresh binder to E leaves
every old fvar rank unchanged and gives the fresh binder rank len(E)+1.

A token multiset is a finite map rank -> count.  Multiset order is the
lexicographic comparison of counts from the HIGHEST rank downwards (this is
equivalent to the Dershowitz-Manna multiset extension for tokens ordered by
rank).  A state measure is (token multiset, secondary type size); compare
token multisets first, then size.  Labels whose atom is in the active set
Sigma are opaque: their contents contribute neither tokens nor size.

This file instruments the *actual* checked algorithm, including the fact that
an obligation discharge calls alg(Eo,C,D) with an EMPTY active set, so the
obligation child measure is taken with Sigma = empty.
"""
import sys, time, random
from functools import lru_cache
sys.setrecursionlimit(1000000)
exec(open('/workspace/.scratch/agent/core.py').read())

EDGES=[]

# ---------------------------------------------------------------- token data
@lru_cache(maxsize=None)
def rank_of(E, X):
    """rank_E(X) = len(E) - 0-based position of X.  None if unbound."""
    n=len(E)
    for i,(y,k,T) in enumerate(E):
        if y==X:
            return n-i
    return None

def addm(d1,d2):
    if not d2: return dict(d1)
    out=dict(d1)
    for r,c in d2.items(): out[r]=out.get(r,0)+c
    return out

@lru_cache(maxsize=None)
def tm(E, Sig, K, T):
    """TM(E,Sigma,K,T): token multiset.

    K is the list of ranks of enclosing type binders, innermost first.
    A b(i) with i < |K| contributes one token at K[i].
    A fresh binder opened under E and K has rank |E|+|K|+1.
    """
    t=T[0]
    if t in ('nat','top','nil'): return {}
    if t=='b':
        i=T[1]
        return {K[i]:1} if i<len(K) else {}
    if t=='v':
        r=rank_of(E,T[1])
        return {r:1} if r is not None else {}
    if t=='arr': return addm(tm(E,Sig,K,T[1]), tm(E,Sig,K,T[2]))
    if t=='all':
        r=len(E)+len(K)+1
        return addm(tm(E,Sig,K,T[1]), tm(E,Sig,(r,)+K,T[2]))
    if t=='mu':
        r=len(E)+len(K)+1
        return tm(E,Sig,(r,)+K,T[1])
    if t=='lab':
        return {} if T[1] in Sig else tm(E,Sig,K,T[2])
    if t=='cons':
        return addm(tm(E,Sig,K,T[2]), tm(E,Sig,K,T[3]))
    raise ValueError(T)

@lru_cache(maxsize=None)
def sz(Sig,T):
    """Secondary size, opaque active labels contribute 1."""
    t=T[0]
    if t in ('nat','top','nil','b','v'): return 1
    if t in ('arr','all'): return 1+sz(Sig,T[1])+sz(Sig,T[2])
    if t=='mu': return 1+sz(Sig,T[1])
    if t=='lab': return 1 if T[1] in Sig else 1+sz(Sig,T[2])
    if t=='cons': return 1+sz(Sig,T[2])+sz(Sig,T[3])
    raise ValueError(T)

def state_measure(E,Sig,A,B):
    toks=addm(tm(E,frozenset(Sig),(),A), tm(E,frozenset(Sig),(),B))
    return toks, sz(frozenset(Sig),A)+sz(frozenset(Sig),B)

def tok_cmp(pm,cm):
    """Return 1 if child tokens < parent tokens, -1 if >, 0 if equal.

    Lexicographic from the highest rank down.  At the highest differing rank
    the side with fewer tokens is the smaller multiset.
    """
    ranks=sorted(set(pm)|set(cm), reverse=True)
    for r in ranks:
        a=pm.get(r,0); b=cm.get(r,0)
        if a!=b:
            return 1 if a>b else -1
    return 0

def mlt(pm,cm):
    """True iff child measure strictly below parent measure (lex)."""
    c=tok_cmp(pm[0],cm[0])
    if c>0: return True          # child token multiset is strictly smaller
    if c<0: return False
    return cm[1] < pm[1]         # equal tokens, secondary size must shrink

# ------------------------------------------------------------- instrumentation
def instrument(E,A,B):
    global EDGES
    EDGES=[]

    def rec(kind, Sp,Ep,Ap,Bp, Sc,Ec,Ac,Bc, **kw):
        EDGES.append((kind,frozenset(Sp),Ep,Ap,Bp,
                            frozenset(Sc),Ec,Ac,Bc,kw))

    def prove(E,A,B,active,Sig):
        if B==TOP and wf_dec(E,A): return True,{}
        if A==NAT and B==NAT and wf_env(E): return True,{}
        if A[0]=='v' and A==B and wf_env(E) and wf_dec(E,A): return True,{}
        if A[0]=='v':
            bb=binds(E,A[1])
            if bb is not None and bb[0]=='sub':
                rec('trans',Sig,E,A,B, Sig,E,bb[1],B)
                return prove(E,bb[1],B,active,Sig)
            return False,{}
        if A[0]=='lab' and B[0]=='lab' and A[1]==B[1]:
            X=A[1]
            if X in active:
                # assertion creates a pending obligation; it is checked at mu
                return True,{X:[(E,A[2],B[2])]}
            rec('lab',Sig,E,A,B, Sig,E,A[2],B[2])
            return prove(E,A[2],B[2],active,Sig)
        if A[0]=='arr' and B[0]=='arr':
            rec('arrow',Sig,E,A,B, Sig,E,B[1],A[1])
            ok,n1=prove(E,B[1],A[1],active,Sig)
            if not ok: return False,{}
            rec('arrow',Sig,E,A,B, Sig,E,A[2],B[2])
            ok,n2=prove(E,A[2],B[2],active,Sig)
            if not ok: return False,{}
            return True,merge(n1,n2)
        if A[0]=='all' and B[0]=='all':
            S1,T1=A[1],A[2]; S2,T2=B[1],B[2]
            rec('all',Sig,E,A,B, Sig,E,S1,S2)
            ok,n1=prove(E,S1,S2,active,Sig)
            if not ok: return False,{}
            rec('all',Sig,E,A,B, Sig,E,S2,S1)
            ok,n2=prove(E,S2,S1,active,Sig)
            if not ok: return False,{}
            X=fresh(atoms_env(E)|atoms_of(A)|atoms_of(B))
            E2=[(X,'sub',S2)]+E
            T1X=open_tt(T1,v(X)); T2X=open_tt(T2,v(X))
            rec('allbody',Sig,E,A,B, Sig,E2,T1X,T2X,X=X)
            ok,n3=prove(E2,T1X,T2X,active,Sig)
            if not ok: return False,{}
            return True,merge(merge(n1,n2),n3)
        if A[0]=='mu' and B[0]=='mu':
            A1,A2=A[1],B[1]
            if not (wf_dec(E,A) and wf_dec(E,B)): return False,{}
            X=fresh(atoms_env(E)|atoms_of(A)|atoms_of(B))
            E2=[(X,'sub',TOP)]+E
            P1=open_tt(A1,v(X)); P2=open_tt(A2,v(X))
            U1=open_tt(A1,lab(X,P1)); U2=open_tt(A2,lab(X,P2))
            if not (wf_dec(E2,P1) and wf_dec(E2,P2)): return False,{}
            Sig2=set(Sig); Sig2.add(X)
            rec('mu',Sig,E,A,B, Sig2,E2,U1,U2,X=X,P1=P1,P2=P2)
            active2=dict(active); active2[X]=(P1,P2)
            ok,needs=prove(E2,U1,U2,active2,Sig2)
            if not ok: return False,{}
            mine=needs.pop(X,[]); seen=set(); oblig=[]
            for o in mine:
                kk=(tuple(o[0]),o[1],o[2])
                if kk in seen: continue
                seen.add(kk); oblig.append(o)
            for o in oblig:
                Eo,C,D=o
                # alg(Eo,C,D) starts with active = empty, hence Sigma = empty
                rec('oblig',Sig,E,A,B, frozenset(),Eo,C,D,X=X)
                ok2=alg_call(Eo,C,D)
                if not ok2: return False,{}
            return True,needs
        if rt_type(A) and rt_type(B):
            if not (wf_env(E) and collectLabel(B)<=collectLabel(A)
                    and wf_dec(E,A) and wf_dec(E,B)): return False,{}
            needs={}
            for i in collectLabel(B):
                t1=Tlookup(i,A); t2=Tlookup(i,B)
                if t1 is None or t2 is None: continue
                rec('rcd',Sig,E,A,B, Sig,E,t1,t2)
                ok,nn=prove(E,t1,t2,active,Sig)
                if not ok: return False,{}
                needs=merge(needs,nn)
            return True,needs
        return False,{}

    def alg_call(E,A,B):
        ok,needs=prove(E,A,B,{},set())
        return ok and not needs

    ok,needs=prove(E,A,B,{},set())
    return (ok and not needs),EDGES

def merge(n1,n2):
    if not n1: return dict(n2)
    out={k:list(v) for k,v in n1.items()}
    for k,v in n2.items(): out.setdefault(k,[]).extend(v)
    return out

# ------------------------------------------------------------------- checking
def check(cases,maxex=3):
    tot={}; bad={}; wfbad={}; nonwf={}
    for (E,A,B) in cases:
        r,edges=instrument(E,A,B)
        for e in edges:
            kind,Sp,Ep,Ap,Bp,Sc,Ec,Ac,Bc,kw=e
            pm=state_measure(Ep,Sp,Ap,Bp)
            cm=state_measure(Ec,Sc,Ac,Bc)
            tot[kind]=tot.get(kind,0)+1
            if not mlt(pm,cm):
                wf=(wf_env(Ep) and wf_dec(Ep,Ap) and wf_dec(Ep,Bp)
                    and wf_env(Ec) and wf_dec(Ec,Ac) and wf_dec(Ec,Bc))
                (wfbad if wf else nonwf).setdefault(kind,[]).append((e,pm,cm,wf))
    return tot,wfbad,nonwf

def report(tot,bad,name,maxex=2):
    print('---',name,'edges',sum(tot.values()))
    for k in sorted(tot):
        b=bad.get(k,[])
        print('  %-8s %6d violations %4d'%(k,tot[k],len(b)))
        for (e,pm,cm,wf) in b[:maxex]:
            kind,Sp,Ep,Ap,Bp,Sc,Ec,Ac,Bc,kw=e
            print('     par tokens',pm[0],'size',pm[1])
            print('       A',Ap,'B',Bp,'E',Ep,'Sig',sorted(Sp),'wf',wf)
            print('     ch  tokens',cm[0],'size',cm[1])
            print('       A',Ac,'B',Bc,'E',Ec,'Sig',sorted(Sc),'kw',kw)

