            if kind in ('trans','arrow','rcd','allbody','lab','mu','oblig'):
                print('  %-7s %s par tok %s sz %d -> ch tok %s sz %d %s'%(
                    kind,'OK ' if okk else 'BAD',pm[0],pm[1],cm[0],cm[1],kw))
        print('  bad edges',bad)

