def gt_depth(E, A, B, maxd=20):
    for d in range(1, maxd + 1):
        memo = {}
        if _can(E, A, B, d, memo):
            return d
    return None

def _can(E, A, B, d, memo):
    if d <= 0:
        return False
    key = (tuple(E), A, B, d)
    v = memo.get(key)
    if v is not None:
        return v
