        res = True

    if A[0] == 'v':
        # sa_fvar
        if (not res) and A == B and wf_dec(E, A):
            res = True
        # sa_trans_tvar (all sub bindings of X)
        if not res:
            X = A[1]
            for (Y, k, U) in E:
                if Y == X and k == 'sub':
                    if _can(E, U, B, d - 1, memo):
                        res = True
                        break

    elif A[0] == 'arr' and B[0] == 'arr':
        if _can(E, B[1], A[1], d - 1, memo) and _can(E, A[2], B[2], d - 1, memo):
