import sys
sys.setrecursionlimit(1000000)

POS = 'P'; NEG = 'N'
def choose(m, C, D):
    return C if m == POS else D
def flip(m):
    return NEG if m == POS else POS

# ---------------- sizes / environment weights / measures ------------------
# structural size, mu = 1 + size(body); fvar/bvar/unit = 1;
# label l P is opaque (weight 1) iff l is in the label environment Sig.
def szS(Sig, T):
    t = T[0]
    if t in ('nat', 'top', 'nil', 'b', 'v'):
        return 1
    if t in ('arr', 'all'):
        return 1 + szS(Sig, T[1]) + szS(Sig, T[2])
    if t == 'mu':
        return 1 + szS(Sig, T[1])
    if t == 'lab':
        return 1 if T[1] in Sig else 1 + szS(Sig, T[2])
    # cons
    return 1 + szS(Sig, T[2]) + szS(Sig, T[3])

def fvT(T):
    return fv_tt(T)

def wE(Sig, E, X):
    """environment expansion weight of fvar X (Task.v-style w)."""
    if not E:
        return 1
    (Y, k, T) = E[0]
    if X == Y:
        if k == 'sub':
            return szS(Sig, T) + sum(wE(Sig, E[1:], Z) for Z in fvT(T))
        return 1
    return wE(Sig, E[1:], X)

def envw(Sig, E, A, B):
    return sum(wE(Sig, E, X) for X in (fvT(A) | fvT(B)))

def measure(name, Sig, E, A, B):
    s = szS(Sig, A) + szS(Sig, B)
    e = envw(Sig, E, A, B)
    if name == 'size':       return s
    if name == 'envw':       return e
    if name == 'sum':        return s + e
    if name == 'size,envw':  return (s, e)
    if name == 'envw,size':  return (e, s)
    if name == 'max,envw':   return (max(szS(Sig, A), szS(Sig, B)), e)
    if name == 'size,maxenv':return (s, max([1] + [wE(Sig, E, X) for X in (fvT(A) | fvT(B))]))
    if name == 'sum,dep':    return (s + e, len(E))
    if name == 'size,rank':
        # sum of ranks (newest binder = length E); unbound = 0
        def rk(X):
            for i, (Y, k, T) in enumerate(E):
                if Y == X:
                    return len(E) - i
            return 0
        return (s, sum(rk(X) for X in (fvT(A) | fvT(B))))
    raise ValueError(name)

MEASURES = ['size', 'envw', 'sum', 'size,envw', 'envw,size',
            'max,envw', 'size,maxenv', 'sum,dep', 'size,rank']

# ---------------- deterministic algorithm ---------------------------------
# Variants:
#   mu_variant:
#     'rec'   : sa_rec-style labelled unfolding on both sides  (declarative)
#     'plain' : open both with the fresh fvar (no label marker)
#     'equiv' : sa_rec unfolding, but require both directions of bodies
#     'one'   : unfold left, compare to right mu; and right, compare to left mu
#   label_variant (only relevant when label atom is in Sig):
#     'rec'    : recurse into payload (declarative sa_label)
#     'true'   : assume it (coinductive / opaque assumption)
#     'equiv'  : require equivalence of payloads
#     'flip'   : recurse with opposite orientation
#   trans_variant:
#     'lhs'    : expand LHS fvar through env sub-bindings
#     'both'   : also expand RHS fvar
#   rcd_variant:
#     'full'   : sa_rcd, incl.  rcd_cons <: rcd_nil
#     'cons'   : only cons/cons (depth.py style)
#   mode: uses the Mode encoding (choose/flip), semantically the same as mode-less
#         when everything is done coherently.

def mk_alg(mu_variant='rec', label_variant='rec', trans_variant='lhs',
           rcd_variant='full', use_mode=False):
    trace = []          # (parent_goal, child_goal, Sig_parent, Sig_child, kind)
    memo = {}
    INPROG = object()

    def record(pctx, cctx, kind):
        trace.append((pctx, cctx, kind))

    def go(m, E, A, B, Sig):
        """goal: sub E (choose m A B) (choose (flip m) A B)"""
        L = choose(m, A, B)
        R = choose(flip(m), A, B)
        key = (m, tuple(E), A, B, Sig) if use_mode else (tuple(E), L, R, Sig)
        st = memo.get(key)
        if st is INPROG:
            return False
        if st is not None:
            return st
        memo[key] = INPROG
        res = False
        if wf_env(E):
            res = step(m, E, A, B, L, R, Sig)
        memo[key] = res
        return res

    def call_child(m, E, A, B, Sig, parent, kind):
        record(parent, (m, tuple(E), A, B, Sig), kind)
        return go(m, E, A, B, Sig)

    def step(m, E, A, B, L, R, Sig):
        parent = (m, tuple(E), A, B, Sig)

        # sa_top
        if R == TOP:
            return wf_dec(E, L)

        # sa_nat
        if L == NAT:
            return R == NAT

        # fvars
        if L[0] == 'v':
            if R[0] == 'v' and L == R and wf_dec(E, L):
                return True
            X = L[1]
            Us = [U for (Y, k, U) in E if Y == X and k == 'sub']
            if Us:
                for U in Us:
                    # child goal: sub E U R   (same orientation m)
                    a2 = choose(m, U, R); b2 = choose(flip(m), U, R)
                    if call_child(m, E, a2, b2, Sig, parent, 'trans'):
                        return True
                return False
            if trans_variant == 'both' and R[0] == 'v':
                Y = R[1]
                Vs = [V for (Z, k, V) in E if Z == Y and k == 'sub']
                for V in Vs:
                    # child goal: sub E L V  (opposite role: expand RHS)
                    a2 = choose(m, L, V); b2 = choose(flip(m), L, V)
                    if call_child(m, E, a2, b2, Sig, parent, 'transR'):
                        return True
            return False

        # arrow
        if L[0] == 'arr':
            if R[0] != 'arr':
                return False
            A1, A2 = L[1], L[2]; B1, B2 = R[1], R[2]
            # domain flips mode, codomain keeps it
            c1 = call_child(flip(m), E, A1, B1, Sig, parent, 'arrow_dom')
            if not c1:
                return False
            return call_child(m, E, A2, B2, Sig, parent, 'arrow_cod')

        # all
        if L[0] == 'all':
            if R[0] != 'all':
                return False
            S1, T1 = L[1], L[2]; S2, T2 = R[1], R[2]
            # the two domain directions = equiv
            if not call_child(m, E, S1, S2, Sig, parent, 'all_dom1'):
                return False
            if not call_child(flip(m), E, S1, S2, Sig, parent, 'all_dom2'):
                return False
            X = fresh(atoms_env(E) | atoms_of(L) | atoms_of(R))
            E2 = [(X, 'sub', choose(flip(m), S1, S2))] + E
            return call_child(m, E2, open_tt(T1, v(X)), open_tt(T2, v(X)), Sig,
                              parent, 'all_body')

        # mu
        if L[0] == 'mu':
            if R[0] != 'mu':
                return False
            A1, A2 = L[1], R[1]
            if not (wf_dec(E, L) and wf_dec(E, R)):
                return False
            X = fresh(atoms_env(E) | atoms_of(L) | atoms_of(R))
            E2 = [(X, 'sub', TOP)] + E
            P1 = open_tt(A1, v(X)); P2 = open_tt(A2, v(X))
            U1 = open_tt(A1, lab(X, P1)); U2 = open_tt(A2, lab(X, P2))
            if not (wf_dec(E2, P1) and wf_dec(E2, P2)):
                return False
            if mu_variant == 'rec':
                Sig2 = Sig | {X}
                return call_child(m, E2, U1, U2, Sig2, parent, 'mu_rec')
            if mu_variant == 'plain':
                return call_child(m, E2, P1, P2, Sig, parent, 'mu_plain')
            if mu_variant == 'equiv':
                Sig2 = Sig | {X}
                if not call_child(m, E2, U1, U2, Sig2, parent, 'mu_rec_fwd'):
                    return False
                return call_child(flip(m), E2, U1, U2, Sig2, parent, 'mu_rec_bwd')
            if mu_variant == 'one':
                # unfold left only, compare against the right mu; same for right
                if not (wf_dec(E, L) and wf_dec(E, R)):
                    return False
                if not call_child(m, E2, U1, U2, Sig | {X}, parent, 'mu_one_l'):
                    return False
                return call_child(flip(m), E2, U1, U2, Sig | {X}, parent, 'mu_one_r')
            raise ValueError(mu_variant)

        # label
        if L[0] == 'lab':
            if R[0] != 'lab' or L[1] != R[1]:
                return False
            A0, B0 = L[2], R[2]
            l = L[1]
            if l in Sig:
                if label_variant == 'true':
                    return True
                if label_variant == 'equiv':
                    if not call_child(m, E, A0, B0, Sig, parent, 'lab_eq1'):
                        return False
                    return call_child(flip(m), E, A0, B0, Sig, parent, 'lab_eq2')
                if label_variant == 'flip':
                    return call_child(flip(m), E, A0, B0, Sig, parent, 'lab_flip')
                # 'rec' falls through
            return call_child(m, E, A0, B0, Sig, parent, 'lab')

        # records
        if rt_type(L):
            if not rt_type(R):
                return False
            if rcd_variant == 'cons' and not (L[0] == 'cons' and R[0] == 'cons'):
                return False
            if not (collectLabel(R) <= collectLabel(L) and wf_dec(E, L) and wf_dec(E, R)):
                return False
            labels = collectLabel(R)
            if not labels:
                return True
            for i in labels:
                t1 = Tlookup(i, L); t2 = Tlookup(i, R)
                if t1 is None or t2 is None:
                    return False
                if not call_child(m, E, t1, t2, Sig, parent, 'rcd'):
                    return False
            return True

        return False

    def run(E, A, B):
        trace.clear(); memo.clear()
        return go(POS, E, A, B, frozenset())

    def run_neg(E, A, B):
        trace.clear(); memo.clear()
        return go(NEG, E, A, B, frozenset())

    run.trace = trace
    run.memo = memo
    run.run_neg = run_neg
    run.reset = lambda: (trace.clear(), memo.clear())
    return run


# candidate with no mode at all (plain function), declarative-faithful shape
def mk_plain(mu_variant='rec', label_variant='rec', trans_variant='lhs',
             rcd_variant='full'):
    return mk_alg(mu_variant, label_variant, trans_variant, rcd_variant, use_mode=False)

