def fvT(T):
    return fv_tt(T)

def fv_occ(T):
    """free fvars with multiplicity (a list)."""
    t = T[0]
    if t == 'v':
        return [T[1]]
    if t in ('nat', 'top', 'nil', 'b'):
        return []
    if t in ('arr', 'all'):
        return fv_occ(T[1]) + fv_occ(T[2])
    if t == 'mu':
        return fv_occ(T[1])
    if t == 'lab':
        return fv_occ(T[2])
    return fv_occ(T[2]) + fv_occ(T[3])

def wE(Sig, E, X):
    if not E:
        return 1
    (Y, k, T) = E[0]
    if X == Y:
        if k == 'sub':
            return szS(Sig, T) + sum(wE(Sig, E[1:], Z) for Z in fvT(T))
        return 1
    return wE(Sig, E[1:], X)

def wEm(Sig, E, X):
    """environment weight with multiplicity at every level."""
    if not E:
        return 1
    (Y, k, T) = E[0]
    if X == Y:
        if k == 'sub':
            return szS(Sig, T) + sum(wEm(Sig, E[1:], Z) for Z in fv_occ(T))
        return 1
    return wEm(Sig, E[1:], X)

def envw(Sig, E, A, B):
    return sum(wE(Sig, E, X) for X in (fvT(A) | fvT(B)))

def envw_m(Sig, E, A, B):
    return sum(wEm(Sig, E, X) for X in (fv_occ(A) + fv_occ(B)))

