# ---------------- deterministic algorithm ---------------------------------
def mk_alg(mu_variant='rec', label_variant='rec', trans_variant='lhs',
           rcd_variant='full', use_mode=False):
    trace = []
    memo = {}
    INPROG = object()

    def go(m, E, A, B, Sig):
        """checks sub E (choose m A B) (choose (flip m) A B)"""
        L = choose(m, A, B); R = choose(flip(m), A, B)
        key = (m, tuple(E), A, B, Sig) if use_mode else (tuple(E), L, R, Sig)
        st = memo.get(key)
        if st is INPROG:
            return False
        if st is not None:
            return st
        memo[key] = INPROG
        res = False
        if wf_env(E):
            res = step(m, E, A, B, L, R, Sig)
        memo[key] = res
        return res

    def child(m, E, A, B, Sig, parent_actual, kind):
        L = choose(m, A, B); R = choose(flip(m), A, B)
        trace.append((parent_actual, (tuple(E), L, R, Sig), kind))
        return go(m, E, A, B, Sig)

    def step(m, E, A, B, L, R, Sig):
        parent = (tuple(E), L, R, Sig)

        # sa_top
        if R == TOP:
            return wf_dec(E, L)
        # sa_nat
        if L == NAT:
            return R == NAT

        # fvars
        if L[0] == 'v':
            if R[0] == 'v' and L == R and wf_dec(E, L):
                return True
            X = L[1]
            Us = [U for (Y, k, U) in E if Y == X and k == 'sub']
            for U in Us:
                a2 = choose(m, U, R); b2 = choose(flip(m), U, R)
                if child(m, E, a2, b2, Sig, parent, 'trans'):
                    return True
            if trans_variant == 'both' and R[0] == 'v':
                Y = R[1]
                for V in [V for (Z, k, V) in E if Z == Y and k == 'sub']:
                    a2 = choose(m, L, V); b2 = choose(flip(m), L, V)
                    if child(m, E, a2, b2, Sig, parent, 'transR'):
                        return True
            return False

        # arrow (both representation args must be arrows)
        if A[0] == 'arr' and B[0] == 'arr':
            A1, A2 = A[1], A[2]; B1, B2 = B[1], B[2]
            if not child(flip(m), E, A1, B1, Sig, parent, 'arrow_dom'):
                return False
            return child(m, E, A2, B2, Sig, parent, 'arrow_cod')

        # all
        if A[0] == 'all' and B[0] == 'all':
            S1, T1 = A[1], A[2]; S2, T2 = B[1], B[2]
            if not child(m, E, S1, S2, Sig, parent, 'all_dom1'):
                return False
            if not child(flip(m), E, S1, S2, Sig, parent, 'all_dom2'):
                return False
            X = fresh(atoms_env(E) | atoms_of(L) | atoms_of(R))
            E2 = [(X, 'sub', choose(flip(m), S1, S2))] + E
            return child(m, E2, open_tt(T1, v(X)), open_tt(T2, v(X)), Sig,
                         parent, 'all_body')

        # mu
        if A[0] == 'mu' and B[0] == 'mu':
            A1, A2 = A[1], B[1]
            if not (wf_dec(E, L) and wf_dec(E, R)):
                return False
            X = fresh(atoms_env(E) | atoms_of(L) | atoms_of(R))
            E2 = [(X, 'sub', TOP)] + E
            P1 = open_tt(A1, v(X)); P2 = open_tt(A2, v(X))
            U1 = open_tt(A1, lab(X, P1)); U2 = open_tt(A2, lab(X, P2))
            if not (wf_dec(E2, P1) and wf_dec(E2, P2)):
                return False
            if mu_variant == 'rec':
                return child(m, E2, U1, U2, Sig | {X}, parent, 'mu_rec')
            if mu_variant == 'plain':
                return child(m, E2, P1, P2, Sig, parent, 'mu_plain')
            if mu_variant == 'equiv':
                if not child(m, E2, U1, U2, Sig | {X}, parent, 'mu_fwd'):
                    return False
                return child(flip(m), E2, U1, U2, Sig | {X}, parent, 'mu_bwd')
            if mu_variant == 'one':
                if not child(m, E2, U1, U2, Sig | {X}, parent, 'mu_one_l'):
                    return False
                return child(flip(m), E2, U1, U2, Sig | {X}, parent, 'mu_one_r')
            raise ValueError(mu_variant)

        # label
        if A[0] == 'lab' and B[0] == 'lab' and A[1] == B[1]:
            A0, B0 = A[2], B[2]
            if A[1] in Sig:
                if label_variant == 'true':
                    return True
                if label_variant == 'equiv':
                    if not child(m, E, A0, B0, Sig, parent, 'lab_eq1'):
                        return False
                    return child(flip(m), E, A0, B0, Sig, parent, 'lab_eq2')
                if label_variant == 'flip':
                    return child(flip(m), E, A0, B0, Sig, parent, 'lab_flip')
                if label_variant == 'rec_drop':
                    return child(m, E, A0, B0, Sig - {A[1]}, parent, 'lab_drop')
            return child(m, E, A0, B0, Sig, parent, 'lab')

        # records
        if rt_type(A) and rt_type(B):
            if rcd_variant == 'cons' and not ((A[0] == 'cons' and B[0] == 'cons')
                                              or (A == NIL and B == NIL)):
                return False
            if not (collectLabel(R) <= collectLabel(L)
                    and wf_dec(E, L) and wf_dec(E, R)):
                return False
            labels = collectLabel(R)
            if not labels:
                return True
            for i in labels:
                t1 = Tlookup(i, L); t2 = Tlookup(i, R)
                if t1 is None or t2 is None:
                    return False
                # child goal: sub t1 t2, encoded with the same mode
                if not child(m, E, choose(m, t1, t2), choose(flip(m), t1, t2),
                             Sig, parent, 'rcd'):
                    return False
            return True

        return False

    def run(E, A, B):
        trace.clear(); memo.clear()
        return go(POS, E, A, B, frozenset())

    def run_neg(E, A, B):
        trace.clear(); memo.clear()
        return go(NEG, E, A, B, frozenset())

    run.trace = trace
    run.memo = memo
    run.run_neg = run_neg
    run.reset = lambda: (trace.clear(), memo.clear())
    return run


