# deterministic collection of all atoms (fvars, label atoms, record labels)
# in a state, in traversal order, then an injective alpha-renaming to 0,1,...
def _collect_atoms_type(T, out, seen):
    t = T[0]
    if t == 'v':
        if T[1] not in seen:
            seen.add(T[1]); out.append(T[1])
    elif t in ('nat', 'top', 'nil', 'b'):
        return
    elif t in ('arr', 'all'):
        _collect_atoms_type(T[1], out, seen); _collect_atoms_type(T[2], out, seen)
    elif t == 'mu':
        _collect_atoms_type(T[1], out, seen)
    elif t == 'lab':
        if T[1] not in seen:
            seen.add(T[1]); out.append(T[1])
        _collect_atoms_type(T[2], out, seen)
    elif t == 'cons':
        if T[1] not in seen:
            seen.add(T[1]); out.append(T[1])
        _collect_atoms_type(T[2], out, seen); _collect_atoms_type(T[3], out, seen)

def _ren_type(T, mp):
    t = T[0]
    if t == 'v':
        return ('v', mp[T[1]])
    if t in ('nat', 'top', 'nil', 'b'):
        return T
    if t == 'arr':
        return ('arr', _ren_type(T[1], mp), _ren_type(T[2], mp))
    if t == 'all':
        return ('all', _ren_type(T[1], mp), _ren_type(T[2], mp))
    if t == 'mu':
        return ('mu', _ren_type(T[1], mp))
    if t == 'lab':
        return ('lab', mp[T[1]], _ren_type(T[2], mp))
    if t == 'cons':
        return ('cons', mp[T[1]], _ren_type(T[2], mp), _ren_type(T[3], mp))
    raise ValueError(t)

def canon_state(E, A, B, Sig):
    out = []; seen = set()
    for (Y, k, T) in E:
        if Y not in seen:
            seen.add(Y); out.append(Y)
        _collect_atoms_type(T, out, seen)
    _collect_atoms_type(A, out, seen)
    _collect_atoms_type(B, out, seen)
    for a in sorted(Sig):
        if a not in seen:
            seen.add(a); out.append(a)
    mp = {a: i for i, a in enumerate(out)}
    E2 = tuple((mp[Y], k, _ren_type(T, mp)) for (Y, k, T) in E)
    Sig2 = frozenset(mp[a] for a in Sig)
    return (E2, _ren_type(A, mp), _ren_type(B, mp), Sig2)

