NGOALS = int(sys.argv[1]) if len(sys.argv) > 1 else 250
MAXD = 18

def gen(d, vs):
    if d <= 0:
        return [C.NAT, C.TOP, (C.v(random.choice(vs)) if vs else C.NAT), C.b(0)][random.randrange(4)]
    c = random.randrange(11)
    if c == 0: return C.NAT
    if c == 1: return C.TOP
    if c == 2 and vs: return C.v(random.choice(vs))
    if c == 3: return C.b(random.randrange(2))
    if c in (4, 5): return C.arr(gen(d-1, vs), gen(d-1, vs))
    if c == 6: return C.allt(gen(d-1, vs), gen(d-1, vs))
    if c in (7, 8): return C.mu(gen(d-1, vs))
    if c == 9: return C.lab(random.randrange(2), gen(d-1, vs))
    return C.NIL if random.randrange(3) == 0 else C.cons(random.randrange(2), gen(d-1, vs), gen(d-1, vs))

