    'plain': A.mk_alg('rec','rec','lhs','full',use_mode=False,
                      step_cap=STEP_CAP, expansion_cap=EXP_CAP, depth_cap=DEPTH_CAP),
    'canon': A.mk_alg('rec','rec','lhs','full',use_mode=False,
                      step_cap=STEP_CAP, expansion_cap=EXP_CAP, depth_cap=DEPTH_CAP,
                      canon=True, canon_mu_label=True),
}
for name, run in runs.items():
    t0 = time.time(); mism = []; aborts = []; mx = [0,0,0]; arg = {}
    checked = 0
