"""Content-credit measure for the plain mode-less algorithm.

Credits are a multiset of natural ranks.  C(E,Sig,L,R) is defined by the
same case analysis as the algorithm and, by construction, is the disjoint
union of the credits of every recursive child plus residual unfolding
tokens.  Consequently the lexicographic pair (C, sz) should strictly
decrease on every recursive edge.
"""
import sys
sys.path.insert(0, '/workspace/.scratch/agent2')
import common as C
from core import (NAT, TOP, NIL, b, v, arr, allt, mu, lab, cons,
                  open_tt, fv_tt, fl_tt, atoms_env, atoms_of, fresh,
                  collectLabel, Tlookup, rt_type)
from alg import szS

MAXR = 10 ** 9          # rank used for a mu-unfolding token


def rankE(E, X):
    for i, (Y, k, T) in enumerate(E):
        if Y == X:
            return len(E) - i
    return 0


def _sum(ms):
    out = []
    for m in ms:
        out.extend(m)
    return tuple(out)


def credits(E, Sig, L, R):
    """Multiset of ranks, represented as a sorted tuple (descending)."""
    return tuple(sorted(_credits(tuple(E), frozenset(Sig), L, R), reverse=True))


def _credits(E, Sig, L, R, memo=None, active=None):
    if memo is None:
        memo = {}
    key = (E, Sig, L, R)
    if key in memo:
        return memo[key]
    if active is None:
        active = set()
    if key in active:
        # fallback for a cyclic measure computation; report via global flag
        CREDIT_CYCLES.append(key)
        return ()
    active.add(key)
    try:
        res = _credits_body(E, Sig, L, R, memo, active)
    finally:
        active.discard(key)
    memo[key] = res
    return res


CREDIT_CYCLES = []


def _credits_body(E, Sig, L, R, memo, active):
    # terminal cases, mirroring step()
    if R == TOP or L == NAT:
        return ()
    if L[0] == 'v':
        if L == R:
            return ()
        X = L[1]
        Us = [U for (Y, k, U) in E if Y == X and k == 'sub']
        if not Us:
            return ()
        children = [_credits(E, Sig, U, R, memo, active) for U in Us]
        return (rankE(E, X),) + _sum(children)

    # arrow: domain child is (R1,L1), codomain child is (L2,R2)
    if L[0] == 'arr' and R[0] == 'arr':
        L1, L2 = L[1], L[2]; R1, R2 = R[1], R[2]
        return (_sum([_credits(E, Sig, R1, L1, memo, active),
                      _credits(E, Sig, L2, R2, memo, active)]))

    # all: two domain children plus body child under binding SR
    if L[0] == 'all' and R[0] == 'all':
        SL, TL = L[1], L[2]; SR, TR = R[1], R[2]
        Z = fresh(set(atoms_env(E)) | set(atoms_of(L)) | set(atoms_of(R)) | set(Sig))
        E2 = ((Z, 'sub', SR),) + E
        PL = open_tt(TL, v(Z)); PR = open_tt(TR, v(Z))
        return _sum([_credits(E, Sig, SL, SR, memo, active),
                     _credits(E, Sig, SR, SL, memo, active),
                     _credits(E2, Sig, PL, PR, memo, active)])

    # mu: child credits plus one high-rank unfolding token
    if L[0] == 'mu' and R[0] == 'mu':
        AL, AR = L[1], R[1]
        Z = fresh(set(atoms_env(E)) | set(atoms_of(L)) | set(atoms_of(R)) | set(Sig))
        E2 = ((Z, 'sub', TOP),) + E
        Sig2 = Sig | {Z}
        PL = open_tt(AL, v(Z)); PR = open_tt(AR, v(Z))
        UL = open_tt(AL, lab(Z, PL)); UR = open_tt(AR, lab(Z, PR))
        return (MAXR,) + _credits(E2, Sig2, UL, UR, memo, active)

    # label: payload plus a label token iff the label is active
    if L[0] == 'lab' and R[0] == 'lab' and L[1] == R[1]:
        base = _credits(E, Sig, L[2], R[2], memo, active)
        if L[1] in Sig:
            return (rankE(E, L[1]),) + base
        return base

    # records: disjoint union over the compared fields
    if rt_type(L) and rt_type(R):
        out = ()
        for i in collectLabel(R):
            t1 = Tlookup(i, L); t2 = Tlookup(i, R)
            if t1 is not None and t2 is not None:
                out = out + _credits(E, Sig, t1, t2, memo, active)
        return out

    return ()


def credits_pair(E, Sig, L, R):
    return credits(E, Sig, L, R)


def size_pair(Sig, L, R):
    return szS(Sig, L) + szS(Sig, R)


def multiset_lt(cchild, cparent):
    """Dershowitz-Manna multiset order on natural ranks (descending)."""
    a = list(cchild); bb = list(cparent)
    n = max(len(a), len(bb))
    a += [-1] * (n - len(a)); bb += [-1] * (n - len(bb))
    for x, y in zip(a, bb):
        if x != y:
            return x < y
    return False


def multiset_subset(cchild, cparent):
    from collections import Counter
    cc = Counter(cchild); cp = Counter(cparent)
    return all(v <= cp[k] for k, v in cc.items())


def check_edge(Ep, Sp, Lp, Rp, Ec, Sc, Lc, Rc, memo=None):
    if memo is None:
        memo = {}
    cp = _credits(tuple(Ep), frozenset(Sp), Lp, Rp, memo)
    cc = _credits(tuple(Ec), frozenset(Sc), Lc, Rc, memo)
    sp = size_pair(Sp, Lp, Rp); sc = size_pair(Sc, Lc, Rc)
    credit_lt = multiset_lt(tuple(sorted(cc, reverse=True)),
                            tuple(sorted(cp, reverse=True)))
    subset = multiset_subset(cc, cp)
    strict_subset = subset and sorted(cc) != sorted(cp)
    size_lt = sc < sp
    ok_credit_size = credit_lt or (sorted(cc) == sorted(cp) and size_lt)
    ok_sum_size = (len(cc) < len(cp)) or (len(cc) == len(cp) and size_lt)
    ok_size_credit = size_lt or (sp == sc and credit_lt)
    return {
        'cp': cp, 'cc': cc, 'sp': sp, 'sc': sc,
        'credit_lt': credit_lt, 'subset': subset,
        'strict_subset': strict_subset,
        'size_lt': size_lt,
        'ok_credit_size': ok_credit_size,
        'ok_sum_size': ok_sum_size,
        'ok_size_credit': ok_size_credit,
    }

