def enum_types(maxsize, atoms, labels=(0, 1), bvars=(0, 1)):
    by = {1: set([NAT, TOP, NIL] + [b(i) for i in bvars] + [v(a) for a in atoms])}
    for s in range(2, maxsize + 1):
        cur = set()
        for t in by.get(s - 1, set()):
            cur.add(mu(t))
            for l in labels:
                cur.add(lab(l, t))
        for s1 in range(1, s - 1):
            s2 = s - 1 - s1
            for a in by.get(s1, ()):
                for c in by.get(s2, ()):
                    cur.add(arr(a, c)); cur.add(allt(a, c))
                    for i in (0, 1):
                        cur.add(cons(i, a, c))
        by[s] = cur
    return by

def struct_size(T):
    t = T[0]
    if t in ('nat', 'top', 'nil', 'b', 'v'): return 1
    if t in ('arr', 'all'): return 1 + struct_size(T[1]) + struct_size(T[2])
    if t == 'mu': return 1 + struct_size(T[1])
    if t == 'lab': return 1 + struct_size(T[2])
    return 1 + struct_size(T[2]) + struct_size(T[3])

def closed_wf_types(maxsize, labels=(0, 1)):
    by = enum_types(maxsize, (), labels)
    out = []
    for s in sorted(by):
        out += [t for t in by[s] if wf_dec([], t)]
    return out

ENVS = {
 'E0_empty': [],
 'E1_top': [(100, 'sub', TOP)],
 'E3_arr': [(100, 'sub', arr(NAT, NAT))],
 'E4_mu': [(100, 'sub', mu(arr(b(0), b(0))))],
 'E5_rcd': [(100, 'sub', cons(0, NAT, NIL))],
 'E6_2b': [(100, 'sub', arr(v(101), v(101))), (101, 'sub', NAT)],
 'E7_2b': [(100, 'sub', v(101)), (101, 'sub', TOP)],
 'E9_3b': [(100, 'sub', v(101)), (101, 'sub', v(102)), (102, 'sub', TOP)],
 'E10_typ': [(100, 'typ', NAT), (101, 'sub', TOP)],
}

def wf_types_for(E, maxsize):
    by = enum_types(maxsize, [x for (x, _, _) in E])
    out = []
    for s in sorted(by):
        out += [t for t in by[s] if wf_dec(E, t)]
    return out

