# ---------- numeric (unit-sum) version, for the Coq measure ----------
def credit_count(E, Sig, L, R):
    return len(credits(E, Sig, L, R))


def check_edge_count(Ep, Sp, Lp, Rp, Ec, Sc, Lc, Rc, memo=None):
    if memo is None:
        memo = {}
    cp = _credits(tuple(Ep), frozenset(Sp), Lp, Rp, memo)
    cc = _credits(tuple(Ec), frozenset(Sc), Lc, Rc, memo)
    sp = size_pair(Sp, Lp, Rp); sc = size_pair(Sc, Lc, Rc)
    ok = len(cc) < len(cp) or (len(cc) == len(cp) and sc < sp)
    return ok, len(cp), len(cc), sp, sc
