import sys,time,random
from collections import Counter,defaultdict
sys.path.insert(0,'/workspace/.scratch/agent2')
import common as C, alg as A, credits as CR
from core import wf_dec,wf_env
run=A.mk_alg('rec','rec','lhs','full',use_mode=False,step_cap=300000,expansion_cap=200000,depth_cap=5000)
stats=Counter(); bykind=defaultdict(Counter); maxcred=0; maxsize=0; first_subset=None; first_cs=None
def check_goal(E,a,b,label):
    global maxcred,maxsize,first_subset,first_cs
    for orient,fn in (('pos',run),('neg',run.run_neg)):
        fn(E,a,b)
        if run.state['aborted']:
            stats['aborts']+=1; continue
        memo={}
        for par,ch,kind in run.trace:
            Ep,Lp,Rp,Sp=par; Ec,Lc,Rc,Sc=ch
            res=CR.check_edge(Ep,Sp,Lp,Rp,Ec,Sc,Lc,Rc,memo)
            stats['edges']+=1; bykind[kind]['edges']+=1
            if len(res['cp'])>maxcred: maxcred=len(res['cp'])
            if max(res['sp'],res['sc'])>maxsize: maxsize=max(res['sp'],res['sc'])
            if not res['subset']:
                stats['subset_fail']+=1; bykind[kind]['subset_fail']+=1
                if first_subset is None: first_subset=(label,orient,kind,par,ch,res)
            if res['credit_lt']:
                stats['credit_lt']+=1; bykind[kind]['credit_lt']+=1
            elif sorted(res['cc'])==sorted(res['cp']):
                stats['equal_credits']+=1; bykind[kind]['equal_credits']+=1
                if res['size_lt']:
                    stats['equal_size_lt']+=1; bykind[kind]['equal_size_lt']+=1
                else:
                    stats['equal_size_NOT_lt']+=1; bykind[kind]['equal_size_NOT_lt']+=1
                    if first_cs is None: first_cs=(label,orient,kind,par,ch,res)
            else:
                stats['credit_incomparable']+=1; bykind[kind]['credit_incomparable']+=1
                if first_cs is None: first_cs=(label,orient,kind,par,ch,res)

# closed size 4
t0=time.time(); tys=C.closed_wf_types(4)
for a in tys:
    for b in tys:
        check_goal([],a,b,'closed4')
print('closed4',round(time.time()-t0,2),dict(stats))
# env size 3
t0=time.time()
for ename,E in C.ENVS.items():
    tys=C.wf_types_for(E,3)
    for a in tys:
        for b in tys:
            check_goal(E,a,b,ename)
print('closed4+env3',round(time.time()-t0,2),dict(stats))
print('bykind:')
for k in sorted(bykind): print(' ',k,dict(bykind[k]))
print('maxcred',maxcred,'maxsize',maxsize)
print('first_subset',str(first_subset)[:900])
print('first_credit_size_fail',str(first_cs)[:900])

