import sys, time, random
sys.path.insert(0,'/workspace/.scratch/agent2')
import common as C, alg as A, credits as CR
from core import wf_dec, wf_env

seed=int(sys.argv[1]) if len(sys.argv)>1 else 424242
random.seed(seed)
run=A.mk_alg('rec','rec','lhs','full',use_mode=False, step_cap=300000, expansion_cap=200000, depth_cap=5000)

def gen(d, depth, vs):
    if d<=0:
        opts=[C.NAT,C.TOP]
        if vs: opts.append(C.v(random.choice(vs)))
        for i in range(depth): opts.append(C.b(i))
        return random.choice(opts)
    c=random.randrange(12)
    if c==0: return C.NAT
    if c==1: return C.TOP
    if c==2 and vs: return C.v(random.choice(vs))
    if c==3 and depth: return C.b(random.randrange(depth))
    if c in (4,5): return C.arr(gen(d-1,depth,vs),gen(d-1,depth,vs))
    if c==6: return C.allt(gen(d-1,depth,vs),gen(d-1,depth+1,vs))
    if c in (7,8,9): return C.mu(gen(d-1,depth+1,vs))
    if c==10: return C.lab(random.randrange(2),gen(d-1,depth,vs))
    return C.NIL if random.randrange(3)==0 else C.cons(random.randrange(2),gen(d-1,depth,vs),gen(d-1,depth,vs))

def draw(d,depth,vs,E,tries=500):
    for _ in range(tries):
        T=gen(d,depth,vs)
        if C.struct_size(T)<=300 and wf_dec(E,T): return T
    return None

def make_goals(n,depth,envlo,envhi,selfprob=0.0):
    closed=C.closed_wf_types(4); goals=[]; tries=0
    while len(goals)<n and tries<n*20:
        tries+=1
        E=[]; vs=[]
        for j in range(random.randrange(envlo,envhi+1)):
            X=20000+tries*6+j
            T=random.choice(closed)
            E=[(X,'sub',T)]+E; vs.append(X)
        if not wf_env(E): continue
        a=draw(depth,0,vs,E)
        if a is None: continue
        b=a if random.random()<selfprob else draw(depth,0,vs,E)
        if b is None or not wf_dec(E,b): continue
        goals.append((E,a,b))
    return goals,tries

def check_suite(name,goals,tlim=90):
    t0=time.time(); counts={'goals':len(goals),'runs':0,'edges':0}
    first={'credit_size':None,'sum_size':None,'size_credit':None}
    maxcred=0; maxedge=None; maxcalls=0; maxdep=0; arg={}
    for gi,(E,a,b) in enumerate(goals):
        if time.time()-t0>tlim:
            print(name,'TIME CUT at goal',gi); break
        for orient,fn in (('pos',run),('neg',run.run_neg)):
            r=fn(E,a,b); counts['runs']+=1
            st=dict(run.state)
            if st['aborted']:
                print(name,'ABORT',orient,E,a,b,st); continue
            if st['calls']>maxcalls: maxcalls=st['calls']; arg['calls']=(gi,orient)
            if st['max_depth']>maxdep: maxdep=st['max_depth']; arg['depth']=(gi,orient)
            memo={}
            for par,ch,kind in run.trace:
                Ep,Lp,Rp,Sp=par; Ec,Lc,Rc,Sc=ch
                counts['edges']+=1
                res=CR.check_edge(Ep,Sp,Lp,Rp,Ec,Sc,Lc,Rc,memo)
                if len(res['cp'])>maxcred:
                    maxcred=len(res['cp']); maxedge=(name,gi,orient,kind,res['cp'],res['cc'])
                for key,okkey in (('credit_size','ok_credit_size'),('sum_size','ok_sum_size'),('size_credit','ok_size_credit')):
                    if first[key] is None and not res[okkey]:
                        first[key]=(name,gi,orient,kind,par,ch,res)
        if (gi+1)%50==0:
            print(name,'progress',gi+1,'runs',counts['runs'],'edges',counts['edges'],'time',round(time.time()-t0,2))
    print(name,'DONE time',round(time.time()-t0,2),counts,'maxcred',maxcred,'maxcalls',maxcalls,'maxdep',maxdep,'arg',arg,'cycles',len(CR.CREDIT_CYCLES))
    print(name,'maxedge',str(maxedge)[:500])
    for k,v in first.items():
        print(name,k,'NONE' if v is None else str(v)[:900])
    return first

g1,t1=make_goals(250,6,2,3,0.1)
print('suite1 goals',len(g1),'tries',t1)
check_suite('depth6-2/3env',g1,70)
if len(CR.CREDIT_CYCLES)<5:
    g2,t2=make_goals(120,8,2,4,0.5)
    print('suite2 goals',len(g2),'tries',t2)
    check_suite('depth8-2/4env',g2,70)
print('total cycles',len(CR.CREDIT_CYCLES))

