        d = state['depth']
        if d > state['max_depth']:
            state['max_depth'] = d
        if depth_cap is not None and d > depth_cap:
            state['depth'] -= 1
            state['aborted'] = 'depth'; raise RunAbort('depth')
        if step_cap is not None and state['calls'] > step_cap:
            state['depth'] -= 1
            state['aborted'] = 'steps'; raise RunAbort('steps')
        try:
            L = choose(m, A, B); R = choose(flip(m), A, B)
            if canon:
                ck = canon_state(E, L, R, Sig)
                key = (m,) + ck if use_mode else ck
            else:
                key = (m, tuple(E), A, B, Sig) if use_mode else (tuple(E), L, R, Sig)
            st = memo.get(key)
            if st is INPROG:
                return False
            if st is not None:
                return st
            state['expansions'] += 1
            if expansion_cap is not None and state['expansions'] > expansion_cap:
                state['aborted'] = 'expansions'; raise RunAbort('expansions')
            memo[key] = INPROG
            res = False
            if wf_env(E):
                res = step(m, E, A, B, L, R, Sig)
            memo[key] = res
            return res
        finally:
            state['depth'] -= 1

    def child(m, E, A, B, Sig, parent_actual, kind):
        L = choose(m, A, B); R = choose(flip(m), A, B)
