            if mu_variant == 'plain':
                return child(m, E2, P1, P2, Sig, parent, 'mu_plain')
            if mu_variant == 'equiv':
                if not child(m, E2, U1, U2, Sig | {X}, parent, 'mu_fwd'):
                    return False
                return child(flip(m), E2, U1, U2, Sig | {X}, parent, 'mu_bwd')
