# ---------------- weight functions ----------------
def mk_we(sigma, fvar_mode='unit', mu_coeff=1, label_mode='sig',
          fvar_coeff=1, base=1, dep=0):
    """Return we(T).  sigma: frozenset/set of opaque labels.
       fvar_mode: 'unit' -> w(fvar)=1 ; 'binding' -> 1+w(binding type)
                  'zero' -> 0
       mu_coeff: w(mu T)=1+mu_coeff*w(T)
       label_mode: 'sig'   -> lab X C weighs 1 if X in sigma else 1+w(C)
                   'all'   -> every label weighs 1 (label erased)
                   'none'  -> every label weighs 1+w(C) (raw)
       dep: account for de Bruijn variables at depth d?  kept simple."""
    sigma=frozenset(sigma)
    cache={}
    def we(E,T):
        key=(T, sigma) if fvar_mode=='unit' else (T, sigma, tuple(E))
        if key in cache: return cache[key]
        t=T[0]
        if t in ('nat','top','nil','b'): r=base
        elif t=='v':
            if fvar_mode=='unit': r=base
            elif fvar_mode=='zero': r=0
            else:
                bb=binds(E,T[1])
                r=base
                if bb is not None: r=base+fvar_coeff*we(E,bb[1])
        elif t=='arr': r=base+we(E,T[1])+we(E,T[2])
        elif t=='all': r=base+we(E,T[1])+we(E,T[2])
        elif t=='mu': r=base+mu_coeff*we(E,T[1])
        elif t=='lab':
            opaque = (T[1] in sigma) if label_mode=='sig' else (label_mode=='all')
            r=base if opaque else base+we(E,T[2])
        else: r=base+we(E,T[2])+we(E,T[3])
        cache[key]=r; return r
    return we

def env_weight(E, we, per_binding=1):
    s=0
    for (x,k,T) in E: s+=per_binding+we(E,T)
    return s

def env_weight_restricted(E, Tlist, we, per_binding=0):
    """Sum, once per distinct free type-variable, the weight of its binding.
       Unbound variables contribute 0.  Label atoms are not free type vars."""
    seen=set(); s=0
    for T in Tlist:
        for Y in fv_tt(T):
            if Y in seen: continue
            seen.add(Y)
            bb=binds(E,Y)
            if bb is not None: s+=per_binding+we(E,bb[1])
    return s

def pending_weight(pending, we):
    s=0
    for (Eo,C,D) in pending: s+=we(Eo,C)+we(Eo,D)
    return s

