    base+=params.get('npend',0)*len(pending)
    if parts: return dict(total=base,goal=goal,envw=ew,pendingw=pw,npend=len(pending))
    return base

def child_state(e):
    return dict(sig=e['csig'],E=e['cE'],A=e['cA'],B=e['cB'],
                pend=e.get('cpend',e.get('pend',[])))

def parent_state(e, oblig_mode='mu'):
    if e['kind']=='oblig' and oblig_mode=='handler':
        return dict(sig=e['sig'],E=e['hE'],A=e['hA'],B=e['hB'],pend=e.get('pend',[]))
    return dict(sig=e['sig'],E=e['E'],A=e['A'],B=e['B'],pend=e.get('pend',[]))

