"""Candidate decision procedures for the inductive `sub` relation.

All work on the tuple AST / E format of core.py.

Algorithms
----------
oracle_sub_depth      : bounded declarative search (ground truth, from depth.py)
decl_search           : deterministic declarative proof search, memo + path cycle,
                        returns (True/False, nsteps).  No assumptions.  (test only)
prove_checked         : sound obligation-cache algorithm (item 5):
                        at mu, active label X -> (P1,P2); a label-X goal is
                        *asserted* and recorded, and every recorded goal is
                        checked afterwards by the same procedure.
prove_assume_mode     : item 3, one-sided mode-indexed assumption, no check.
prove_assume_both     : naive equiv/coinductive assumption, no check.
prove_assume_literal  : one-sided literal pair assumption without modes.
"""
import sys
sys.setrecursionlimit(1000000)
exec(open('/workspace/.scratch/agent/core.py').read())

# ---------------------------------------------------------------- oracle
def sub_depth(E,A,B,maxd):
    if maxd<=0: return None
    if B==TOP and wf_dec(E,A): return 1
    if A==NAT and B==NAT and wf_env(E): return 1
    if A[0]=='v' and A==B and wf_env(E) and wf_dec(E,A): return 1
    if A[0]=='v':
        bb=binds(E,A[1])
        if bb is not None and bb[0]=='sub':
            r=sub_depth(E,bb[1],B,maxd-1)
            if r is not None: return r+1
        return None
    if A[0]=='lab' and B[0]=='lab' and A[1]==B[1]:
        r=sub_depth(E,A[2],B[2],maxd-1)
        if r is not None: return r+1
        return None
    if A[0]=='arr' and B[0]=='arr':
        r1=sub_depth(E,B[1],A[1],maxd-1)
        if r1 is None: return None
        r2=sub_depth(E,A[2],B[2],maxd-1)
        if r2 is None: return None
        return max(r1,r2)+1
    if A[0]=='all' and B[0]=='all':
        S1,T1=A[1],A[2]; S2,T2=B[1],B[2]
        r1=sub_depth(E,S1,S2,maxd-1)
        if r1 is None: return None
        r2=sub_depth(E,S2,S1,maxd-1)
        if r2 is None: return None
        X=fresh(atoms_env(E)|atoms_of(A)|atoms_of(B))
        E2=[(X,'sub',S2)]+E
        r3=sub_depth(E2,open_tt(T1,v(X)),open_tt(T2,v(X)),maxd-1)
        if r3 is None: return None
        return max(r1,r2,r3)+1
    if A[0]=='mu' and B[0]=='mu':
        A1,A2=A[1],B[1]
        if not (wf_dec(E,A) and wf_dec(E,B)): return None
        X=fresh(atoms_env(E)|atoms_of(A)|atoms_of(B))
        E2=[(X,'sub',TOP)]+E
        P1=open_tt(A1,v(X)); P2=open_tt(A2,v(X))
        U1=open_tt(A1,lab(X,P1)); U2=open_tt(A2,lab(X,P2))
        if not (wf_dec(E2,P1) and wf_dec(E2,P2)): return None
        r=sub_depth(E2,U1,U2,maxd-1)
        if r is not None: return r+1
        return None
    if rt_type(A) and rt_type(B):
        if not (wf_env(E) and rt_type(A) and rt_type(B) and collectLabel(B)<=collectLabel(A) and wf_dec(E,A) and wf_dec(E,B)): return None
        mx=0
        for i in collectLabel(B):
            t1=Tlookup(i,A); t2=Tlookup(i,B)
            if t1 is None or t2 is None: continue
            r=sub_depth(E,t1,t2,maxd-1)
            if r is None: return None
            mx=max(mx,r)
        return mx+1
    if A==NIL and B==NIL and wf_env(E): return 1
    return None

def sub_oracle(E,A,B,cap=20):
    """returns (value, depth_or_cap, unknown). unknown=True means no proof up to cap."""
    for lim in range(1,cap+1):
        d=sub_depth(E,A,B,lim)
        if d is not None: return True,d,False
    return False,cap,True

# ------------------------------------------------- deterministic declarative search
# No assumptions at all; explicit path set detects infinite branches.
# The rule set is syntax-directed so a repeated goal on the path means failure.
class Budget(Exception): pass

def decl_search(E,A,B,memo=None,path=None,steps=None,maxsteps=200000):
    if steps is None: steps=[0]
    if memo is None: memo={}
    if path is None: path=set()
    key=(tuple(E),A,B)
    if key in memo: return memo[key]
    if key in path: return False
    steps[0]+=1
    if steps[0]>maxsteps: raise Budget()
    path=path|{key}
    def go(): return decl_search(E,A,B,memo,path,steps,maxsteps)
    r=None
    if B==TOP and wf_dec(E,A):
        r=True
    elif A==NAT and B==NAT and wf_env(E):
        r=True
    elif A[0]=='v' and A==B and wf_env(E) and wf_dec(E,A):
        r=True
    elif A[0]=='v':
        bb=binds(E,A[1])
        if bb is not None and bb[0]=='sub':
            r=decl_search(E,bb[1],B,memo,path,steps,maxsteps)
        else: r=False
    elif A[0]=='lab' and B[0]=='lab' and A[1]==B[1]:
        r=decl_search(E,A[2],B[2],memo,path,steps,maxsteps)
    elif A[0]=='arr' and B[0]=='arr':
        r=decl_search(E,B[1],A[1],memo,path,steps,maxsteps) and \
          decl_search(E,A[2],B[2],memo,path,steps,maxsteps)
    elif A[0]=='all' and B[0]=='all':
        S1,T1=A[1],A[2]; S2,T2=B[1],B[2]
        r=decl_search(E,S1,S2,memo,path,steps,maxsteps) and \
          decl_search(E,S2,S1,memo,path,steps,maxsteps)
        if r:
            X=fresh(atoms_env(E)|atoms_of(A)|atoms_of(B))
            E2=[(X,'sub',S2)]+E
            r=decl_search(E2,open_tt(T1,v(X)),open_tt(T2,v(X)),memo,path,steps,maxsteps)
    elif A[0]=='mu' and B[0]=='mu':
        A1,A2=A[1],B[1]
        if not (wf_dec(E,A) and wf_dec(E,B)): r=False
        else:
            X=fresh(atoms_env(E)|atoms_of(A)|atoms_of(B))
            E2=[(X,'sub',TOP)]+E
            P1=open_tt(A1,v(X)); P2=open_tt(A2,v(X))
            U1=open_tt(A1,lab(X,P1)); U2=open_tt(A2,lab(X,P2))
            if not (wf_dec(E2,P1) and wf_dec(E2,P2)): r=False
            else: r=decl_search(E2,U1,U2,memo,path,steps,maxsteps)
    elif rt_type(A) and rt_type(B):
        if not (wf_env(E) and rt_type(A) and rt_type(B) and collectLabel(B)<=collectLabel(A)
                and wf_dec(E,A) and wf_dec(E,B)): r=False
        else:
            r=True
            for i in collectLabel(B):
                t1=Tlookup(i,A); t2=Tlookup(i,B)
                if t1 is None or t2 is None: continue
                if not decl_search(E,t1,t2,memo,path,steps,maxsteps): r=False; break
    elif A==NIL and B==NIL and wf_env(E):
        r=True
    else:
        r=False
    memo[key]=r
    return r

def decl_search_top(E,A,B,maxsteps=200000):
    steps=[0]
    try:
        r=decl_search(E,A,B,{},set(),steps,maxsteps)
        return r,steps[0],False
    except Budget:
        return None,steps[0],True

# ------------------------------------------- checked obligation algorithm (item 5)
# prove(E,A,B,active) -> (ok, needs)
#   active : dict label -> (P1,P2)  (fresh labels of enclosing mu-unfoldings)
#   needs  : dict label -> list of (E',C,D) obligations asserted for that label
# At a mu-vs-mu goal, we add X->(P1,P2), search U1<:U2, then discharge the
# obligations asserted for X by calling alg on them; other labels' needs bubble up.
class StepLimit(Exception): pass

def _fresh_for(E,*Ts):
    s=atoms_env(E)
    for T in Ts: s|=atoms_of(T)
    return fresh(s)

def alg(E,A,B,memo=None,steps=None,maxsteps=500000):
    """top-level sound&complete obligation-cache decision procedure."""
    if memo is None: memo={}
    if steps is None: steps=[0]
    key=(tuple(E),A,B)
    if key in memo: return memo[key]
    steps[0]+=1
    if steps[0]>maxsteps: raise StepLimit()
    ok,needs=prove(E,A,B,{},steps,maxsteps)
    # no active labels at top, so needs must be empty
    r=ok and not needs
    memo[key]=r
    return r

def prove(E,A,B,active,steps,maxsteps):
    steps[0]+=1
    if steps[0]>maxsteps: raise StepLimit()
    if B==TOP and wf_dec(E,A): return True,{}
    if A==NAT and B==NAT and wf_env(E): return True,{}
    if A[0]=='v' and A==B and wf_env(E) and wf_dec(E,A): return True,{}
    if A[0]=='v':
        bb=binds(E,A[1])
        if bb is not None and bb[0]=='sub':
            return prove(E,bb[1],B,active,steps,maxsteps)
        return False,{}
    if A[0]=='lab' and B[0]=='lab' and A[1]==B[1]:
        X=a=A[1]
        if X in active:
            # assert literal obligation  sub E A[2] B[2]
            d={}
            d[X]=[(E,A[2],B[2])]
            return True,d
        return prove(E,A[2],B[2],active,steps,maxsteps)
    if A[0]=='arr' and B[0]=='arr':
        ok1,n1=prove(E,B[1],A[1],active,steps,maxsteps)
        if not ok1: return False,{}
        ok2,n2=prove(E,A[2],B[2],active,steps,maxsteps)
        if not ok2: return False,{}
        return True,merge_needs(n1,n2)
    if A[0]=='all' and B[0]=='all':
        S1,T1=A[1],A[2]; S2,T2=B[1],B[2]
        ok,n1=prove(E,S1,S2,active,steps,maxsteps)
        if not ok: return False,{}
        ok,n2=prove(E,S2,S1,active,steps,maxsteps)
        if not ok: return False,{}
        X=_fresh_for(E,A,B)
        E2=[(X,'sub',S2)]+E
        ok,n3=prove(E2,open_tt(T1,v(X)),open_tt(T2,v(X)),active,steps,maxsteps)
        if not ok: return False,{}
        return True,merge_needs(merge_needs(n1,n2),n3)
    if A[0]=='mu' and B[0]=='mu':
        A1,A2=A[1],B[1]
        if not (wf_dec(E,A) and wf_dec(E,B)): return False,{}
        X=_fresh_for(E,A,B)
        E2=[(X,'sub',TOP)]+E
        P1=open_tt(A1,v(X)); P2=open_tt(A2,v(X))
        U1=open_tt(A1,lab(X,P1)); U2=open_tt(A2,lab(X,P2))
        if not (wf_dec(E2,P1) and wf_dec(E2,P2)): return False,{}
        active2=dict(active); active2[X]=(P1,P2)
        ok,needs=prove(E2,U1,U2,active2,steps,maxsteps)
        if not ok: return False,{}
        mine=needs.pop(X,[])
        # discharge obligations for this mu (dedupe)
        seen=set()
        for (Eo,C,D) in mine:
            kk=(tuple(Eo),C,D)
            if kk in seen: continue
            seen.add(kk)
            if not alg(Eo,C,D,None,steps,maxsteps):
                return False,{}
        return True,needs
    if rt_type(A) and rt_type(B):
        if not (wf_env(E) and rt_type(A) and rt_type(B) and collectLabel(B)<=collectLabel(A)
                and wf_dec(E,A) and wf_dec(E,B)): return False,{}
        needs={}
        for i in collectLabel(B):
            t1=Tlookup(i,A); t2=Tlookup(i,B)
            if t1 is None or t2 is None: continue
            ok,nn=prove(E,t1,t2,active,steps,maxsteps)
            if not ok: return False,{}
            needs=merge_needs(needs,nn)
        return True,needs
    if A==NIL and B==NIL and wf_env(E): return True,{}
    return False,{}

def merge_needs(n1,n2):
    if not n1: return dict(n2)

