"""Focused test: does resolve preprocessing keep M decreasing?

Records, for the checked algorithm, a consumed-fvar set D on every call path.
D starts empty; at trans X -> U we add X to D.  The corrected measure is
    M(S,E,D,A,B) = we_S(A) + we_S(B) + EW_S(E \\ D)
where EW sums we of binding types for bindings whose variable is NOT in D.
The old measure is M with D permanently empty.
"""
import sys, random, time
sys.setrecursionlimit(1000000)
exec(open('/workspace/.scratch/agent/core.py').read())

EDGES=[]

def we(S,T):
    t=T[0]
    if t in ('nat','top','nil','b','v'): return 1
    if t in ('arr','all'): return 1+we(S,T[1])+we(S,T[2])
    if t=='mu': return 1+we(S,T[1])
    if t=='lab': return 1 if T[1] in S else 1+we(S,T[2])
    return 1+we(S,T[2])+we(S,T[3])

def EW(S,E,D):
    s=0
    for (x,k,T) in E:
        if x not in D: s+=we(S,T)
    return s

def M(S,E,D,A,B): return we(S,A)+we(S,B)+EW(S,E,D)

def merge(n1,n2):
    if not n1: return dict(n2)
    out={k:list(v) for k,v in n1.items()}
    for k,v in n2.items(): out.setdefault(k,[]).extend(v)
    return out

def instrument(E,A,B):
    global EDGES
    EDGES=[]
    Sig=set()
    def prove(E,A,B,active,D):
        if B==TOP and wf_dec(E,A): return True,{}
        if A==NAT and B==NAT and wf_env(E): return True,{}
        if A[0]=='v' and A==B and wf_env(E) and wf_dec(E,A): return True,{}
        if A[0]=='v':
            bb=binds(E,A[1])
            if bb is not None and bb[0]=='sub':
                D2=frozenset(set(D)|{A[1]})
                EDGES.append(('trans',set(Sig),E,D,A,B,E,D2,bb[1],B))
                return prove(E,bb[1],B,active,D2)
            return False,{}
        if A[0]=='lab' and B[0]=='lab' and A[1]==B[1]:
            X=A[1]
            if X in active:
                EDGES.append(('assert',set(Sig),E,D,A,B,E,D,A[2],B[2]))
                return True,{X:[(E,A[2],B[2])]}
            EDGES.append(('lab',set(Sig),E,D,A,B,E,D,A[2],B[2]))
            return prove(E,A[2],B[2],active,D)
        if A[0]=='arr' and B[0]=='arr':
            EDGES.append(('arrow',set(Sig),E,D,A,B,E,D,B[1],A[1]))
            ok,n1=prove(E,B[1],A[1],active,D)
            if not ok: return False,{}
            EDGES.append(('arrow',set(Sig),E,D,A,B,E,D,A[2],B[2]))
            ok,n2=prove(E,A[2],B[2],active,D)
            if not ok: return False,{}
            return True,merge(n1,n2)
        if A[0]=='all' and B[0]=='all':
            S1,T1=A[1],A[2]; S2,T2=B[1],B[2]
            EDGES.append(('all',set(Sig),E,D,A,B,E,D,S1,S2))
            ok,n1=prove(E,S1,S2,active,D)
            if not ok: return False,{}
            EDGES.append(('all',set(Sig),E,D,A,B,E,D,S2,S1))
            ok,n2=prove(E,S2,S1,active,D)
            if not ok: return False,{}
            X=fresh(atoms_env(E)|atoms_of(A)|atoms_of(B))
            E2=[(X,'sub',S2)]+E
            EDGES.append(('allbody',set(Sig),E,D,A,B,E2,D,open_tt(T1,v(X)),open_tt(T2,v(X))))
            ok,n3=prove(E2,open_tt(T1,v(X)),open_tt(T2,v(X)),active,D)
            if not ok: return False,{}
            return True,merge(merge(n1,n2),n3)
        if A[0]=='mu' and B[0]=='mu':
            A1,A2=A[1],B[1]
            if not (wf_dec(E,A) and wf_dec(E,B)): return False,{}
            X=fresh(atoms_env(E)|atoms_of(A)|atoms_of(B))
            E2=[(X,'sub',TOP)]+E
            P1=open_tt(A1,v(X)); P2=open_tt(A2,v(X))
            U1=open_tt(A1,lab(X,P1)); U2=open_tt(A2,lab(X,P2))
            if not (wf_dec(E2,P1) and wf_dec(E2,P2)): return False,{}
            Sig.add(X)
            EDGES.append(('mu',set(Sig),E,D,A,B,E2,D,U1,U2,X,P1,P2,E2))
            active2=dict(active); active2[X]=(P1,P2)
            ok,needs=prove(E2,U1,U2,active2,D)
            if not ok:
                Sig.discard(X); return False,{}
            mine=needs.pop(X,[]); seen=set(); oblig=[]
            for o in mine:
                kk=(tuple(o[0]),o[1],o[2])
                if kk in seen: continue
                seen.add(kk); oblig.append(o)
            for o in oblig:
                Eo,C,Dd=o
                # obligation call is a child of the mu invocation; inherit Dframe
                EDGES.append(('oblig',set(Sig),E,D,A,B,Eo,D,C,Dd,X,P1,P2))
                ok2=alg(Eo,C,Dd)
                if not ok2:
                    Sig.discard(X); return False,{}
            Sig.discard(X)
            return True,needs
        if rt_type(A) and rt_type(B):
            if not (wf_env(E) and collectLabel(B)<=collectLabel(A)
                    and wf_dec(E,A) and wf_dec(E,B)): return False,{}
            needs={}
            for i in collectLabel(B):
                t1=Tlookup(i,A); t2=Tlookup(i,B)
                if t1 is None or t2 is None: continue
                EDGES.append(('rcd',set(Sig),E,D,A,B,E,D,t1,t2))
                ok,nn=prove(E,t1,t2,active,D)
                if not ok: return False,{}
                needs=merge(needs,nn)
            return True,needs
        return False,{}
    def alg(E,A,B):
        ok,needs=prove(E,A,B,{},frozenset())
        return ok and not needs
    return alg(E,A,B),EDGES,Sig

def check(cases):
    tot={}; bad={}; badold={}
    for (E,A,B) in cases:
        r,edges,_=instrument(E,A,B)
        for e in edges:
            k=e[0]
            if k=='assert': continue
            S=e[1]; Ep=e[2]; Dp=e[3]; Ap=e[4]; Bp=e[5]
            Ec=e[6]; Dc=e[7]; Ac=e[8]; Bc=e[9]
            pm=M(S,Ep,Dp,Ap,Bp); cm=M(S,Ec,Dc,Ac,Bc)
            tot[k]=tot.get(k,0)+1
            if not cm<pm:
                bad.setdefault(k,[]).append((e,pm,cm))
            # old measure ignores D (uses full EW)
            pmo=we(S,Ap)+we(S,Bp)+EW(S,Ep,frozenset())
            cmo=we(S,Ac)+we(S,Bc)+EW(S,Ec,frozenset())
            if not cmo<pmo:
                badold.setdefault(k,[]).append((e,pmo,cmo))
    return tot,bad,badold

def report(tot,bad,badold,name,maxex=2):
    print('---',name,'edges',sum(tot.values()))
    for k in sorted(tot):
        print('  %-8s %5d corrected-viol %4d old-viol %4d'%(k,tot[k],len(bad.get(k,[])),len(badold.get(k,[]))))
        for (e,pm,cm) in bad.get(k,[])[:maxex]:
            print('     CORR par',pm,'ch',cm,'A',e[4],'B',e[5],'D',e[3],'->',e[8],e[9],'Dc',e[7])
        for (e,pm,cm) in badold.get(k,[])[:maxex]:
            print('     OLD  par',pm,'ch',cm,'A',e[4],'B',e[5],'->',e[8],e[9],'E',e[2],'Ec',e[6])

# ---------------- explicit dangerous cases ----------------
def bigU(k=8):
    U=NAT
    for _ in range(k): U=arr(U,NAT)
    return U

def dangerous():
    U=bigU(8); X=1000
    E=[(X,'sub',U)]
    cases=[]
    cases.append(('arrow dom child fvar',E,arr(U,NAT),arr(v(X),NAT)))
    cases.append(('arrow dom TOP',E,arr(TOP,NAT),arr(v(X),NAT)))
    cases.append(('rcd lookup fvar',E,cons(0,v(X),NIL),cons(0,NAT,NIL)))
    cases.append(('allbody fvar',E,allt(NAT,v(X)),allt(NAT,NAT)))
    cases.append(('label content fvar',E,lab(0,v(X)),lab(0,NAT)))
    return U,cases

if __name__=='__main__':
    t0=time.time()
    U,cases=dangerous()
    print('huge U weight',we(set(),U),'U size',size(U))
    for nm,E,A,B in cases:
        print('\nCASE',nm,'WF',wf_dec(E,A),wf_dec(E,B),'E',E,'A',A,'B',B)
        r,edges,S=instrument(E,A,B)
        print(' result',r)
        for e in edges:
            if e[0]=='assert': continue
            k=e[0]; Sp=e[1]; Ep=e[2]; Dp=e[3]; Ap=e[4]; Bp=e[5]
            Ec=e[6]; Dc=e[7]; Ac=e[8]; Bc=e[9]
            print('  ',k,'old',we(Sp,Ap)+we(Sp,Bp)+EW(Sp,Ep,frozenset()),
                  '->',we(Sp,Ac)+we(Sp,Bc)+EW(Sp,Ec,frozenset()),
                  '| corrected',M(Sp,Ep,Dp,Ap,Bp),'->',M(Sp,Ec,Dc,Ac,Bc),
                  '|',Ap,Bp,'->',Ac,Bc,'D',Dp,'Dc',Dc)
    # ---- batteries ----
    import harness
    from measure_run import enum_terms, hasb
    terms=enum_terms(3)
    keep=[T for T in terms if hasb(T) and wf_dec([],mu(T))]
    ex=[([],mu(T1),mu(T2)) for T1 in keep for T2 in keep]
    random.seed(99); rand=[]; tried=0
    while len(rand)<500 and tried<5000:
        tried+=1
        c=harness.gen_random_case(d=5,nenv=2)
        if c is None: continue
        E,A,B=c
        if wf_dec(E,A) and wf_dec(E,B): rand.append(c)
    hard=[c[1:] for c in cases]
    for name,cs in (('exhaustive size3',ex),('random depth5',rand),('dangerous',hard)):
        tot,bad,badold=check(cs)
        report(tot,bad,badold,name)
    print('time',round(time.time()-t0,2))

