    if c==2 and vs: return v(random.choice(vs))
    if c==3 and depth: return b(random.randrange(depth))
    if c in (4,5): return arr(gen(d-1,depth,vs),gen(d-1,depth,vs))
    if c==6: return allt(gen(d-1,depth,vs),gen(d-1,depth+1,vs))
    if c in (7,8,9): return mu(gen(d-1,depth+1,vs))
    if c==10: return lab(random.randrange(2),gen(d-1,depth,vs))
    return NIL if random.randrange(3)==0 else cons(random.randrange(2),gen(d-1,depth,vs),gen(d-1,depth,vs))

def draw(d,depth,vs,E,tries=200):
    for _ in range(tries):
        T=gen(d,depth,vs)
        if size(T)<=40 and wf_dec(E,T): return T
    return None

def make_goals(n,depth,envlo,envhi,selfprob=0.0,seed=1):
    random.seed(seed); closed=C.closed_wf_types(4); goals=[]; tries=0
    while len(goals)<n and tries<n*30:
        tries+=1
        E=[]; vs=[]
        for j in range(random.randrange(envlo,envhi+1)):
            X=20000+tries*8+j
            T=random.choice(closed)
            E=[(X,'sub',T)]+E; vs.append(X)
        if not wf_env(E): continue
        a=draw(depth,0,vs,E)
        if a is None: continue
        b=a if random.random()<selfprob else draw(depth,0,vs,E)
        if b is None or not wf_dec(E,b): continue
        goals.append((E,a,b))
    return goals

