from measure_correct import wb as Wc
def W(S,E,T,memo=None,stack=None): return Wc(S,E,T)
# Redefine M recursively: base W + OBfull where OBfull unfolds fvars/all/mu/label/rcd using same algorithm branch structure, but labels add W payload.
from functools import lru_cache
def OBfull(S,E,A,B,active_only=False):
    # memo with stack
    memo={}; stack=set()
    def rec(E,A,B):
        key=(tuple(E),A,B)
        if key in memo: return memo[key]
        if key in stack: return 0
        stack.add(key)
        # mirror sub algorithms branch; S fixed
        if B==TOP or A==NAT: r=0
        elif A[0]=='v':
            bb=binds(E,A[1]); r=rec(E,bb[1],B) if bb is not None else 0
        elif A[0]=='arr' and B[0]=='arr': r=rec(E,B[1],A[1])+rec(E,A[2],B[2])
        elif A[0]=='all' and B[0]=='all':
            S1,T1=A[1],A[2]; S2,T2=B[1],B[2]
            X=fresh(atoms_env(E)|atoms_of(A)|atoms_of(B)); E2=[(X,'sub',S2)]+E
            r=rec(E,S1,S2)+rec(E,S2,S1)+rec(E2,open_tt(T1,v(X)),open_tt(T2,v(X)))
        elif A[0]=='mu' and B[0]=='mu':
            A1,A2=A[1],B[1]; X=fresh(atoms_env(E)|atoms_of(A)|atoms_of(B)); E2=[(X,'sub',TOP)]+E
            P1=open_tt(A1,v(X)); P2=open_tt(A2,v(X)); U1=open_tt(A1,lab(X,P1)); U2=open_tt(A2,lab(X,P2))
            # active X; include label payload contribution as W payload plus recursive
            r=W(S|{X},E2,P1)+W(S|{X},E2,P2)+rec(E2,U1,U2)
        elif A[0]=='lab' and B[0]=='lab' and A[1]==B[1]:
            r=(W(S,E,A[2]) if ((not active_only) or A[1] in S) else 0)+rec(E,A[2],B[2])
        elif rt_type(A) and rt_type(B):
            r=0
            for i in collectLabel(B):
                t1=Tlookup(i,A); t2=Tlookup(i,B)
                if t1 is not None and t2 is not None: r+=rec(E,t1,t2)
        else: r=0
        stack.discard(key); memo[key]=r; return r
    return rec(list(E),A,B)
def M2(Sig,E,A,B,active_only=False): return base(Sig,E,A,B)+OBfull(Sig,E,A,B,active_only)
