MAXR=10**9

def rankE(E,X):
    for i,(Y,k,T) in enumerate(E):
        if Y==X: return len(E)-i
    return 0

def toks(Sig,E,T,include_bound=True,freshrank=None):
    t=T[0]
    if t in ('nat','top','nil','b'): return []
    if t=='v':
        r=rankE(E,T[1])
        if r==0 and T[1] not in [Y for Y,_,_ in E]:
            return [0] if include_bound else []
        return [r]
    if t=='arr' or t=='all': return toks(Sig,E,T[1],include_bound)+toks(Sig,E,T[2],include_bound)
    if t=='mu': return [MAXR]+toks(Sig,E,T[1],include_bound)
    if t=='lab':
        base=toks(Sig,E,T[2],include_bound)
        return ([rankE(E,T[1])] if T[1] in Sig else [])+base
    return toks(Sig,E,T[2],include_bound)+toks(Sig,E,T[3],include_bound)

def mt(a,b):
    a=sorted(a,reverse=True); b=sorted(b,reverse=True)
    n=max(len(a),len(b)); a=a+[-1]*(n-len(a)); b=b+[-1]*(n-len(b))
    for x,y in zip(a,b):
        if x!=y: return x<y
    return False

def check_edges(goals,label,limit=60):
    run=A.mk_alg('rec','rec','lhs','full',use_mode=False,step_cap=300000,expansion_cap=200000,depth_cap=5000)
    stats={'edges':0,'bad':0}; ex=[]
    t0=time.time()
    for gi,(E,a,b) in enumerate(goals):
        if time.time()-t0>limit: print(label,'CUT',gi); break
        run(E,a,b)
        if run.state['aborted']: continue
        for par,ch,kind in run.trace:
            Ep,Lp,Rp,Sp=par; Ec,Lc,Rc,Sc=ch
            stats['edges']+=1
            Pp=toks(Sp,Ep,Lp)+toks(Sp,Ep,Rp); Pc=toks(Sc,Ec,Lc)+toks(Sc,Ec,Rc)
            sp=szS(Sp,Lp)+szS(Sp,Rp); sc=szS(Sc,Lc)+szS(Sc,Rc)
            ok=mt(Pc,Pp) or (sorted(Pc)==sorted(Pp) and sc<sp)
            if not ok:
                stats['bad']+=1
                if len(ex)<5: ex.append((kind,par,ch,sorted(Pp,reverse=True),sorted(Pc,reverse=True),sp,sc))
    print(label,stats,'time',round(time.time()-t0,2))
    for e in ex: print(' EX',str(e)[:700])

