from alg import szS
from core import *

def mk_we(Sig,E,T,mode='binding',mu=1,label='sig',fc=1,base=1,active_mode='opaque'):
    Sig=frozenset(Sig); memo={}; active=set()
    def we(E,T):
        key=(tuple(E),T)
        if key in memo: return memo[key]
        if key in active: return 0
        active.add(key)
        t=T[0]
        if t in ('nat','top','nil','b'): r=base
        elif t=='v':
            if mode=='unit': r=base
            elif mode=='zero': r=0
            else:
                bb=None
                for (Y,k,U) in E:
                    if Y==T[1] and k=='sub': bb=U; break
                r=base+(fc*we(E,bb) if bb is not None else 0)
        elif t in ('arr','all'): r=base+we(E,T[1])+we(E,T[2])
        elif t=='mu': r=base+mu*we(E,T[1])
        elif t=='lab':
            opaque=(T[1] in Sig) if label=='sig' else (label=='all')
            r=base if opaque else base+we(E,T[2])
        else: r=base+we(E,T[2])+we(E,T[3])
        active.discard(key); memo[key]=r; return r
    return we(E,T)

def val(Sig,E,L,R,mode='binding',mu=1,label='sig',fc=1,envw=0,perbind=0):
    w1=mk_we(Sig,E,L,mode,mu,label,fc)
    w2=mk_we(Sig,E,R,mode,mu,label,fc)
    ew=0
    if envw:
        seen=set()
        for T in (L,R):
            for X in fv_tt(T):
                if X in seen: continue
                seen.add(X)
                bb=None
                for (Y,k,U) in E:
                    if Y==X and k=='sub': bb=U; break
                if bb is not None: ew+=perbind+mk_we(Sig,E,bb,mode,mu,label,fc)
    return w1+w2+envw*ew

