 if t=='mu': return 1+raw(T[1])
 if t=='lab': return 1+raw(T[2])
 return 1+raw(T[2])+raw(T[3])
def md(T):
 t=T[0]
 if t in ('nat','top','nil','b','v'): return 0
 if t in ('arr','all'): return max(md(T[1]),md(T[2]))
 if t=='mu': return 1+md(T[1])
 if t=='lab': return md(T[2])
 return max(md(T[2]),md(T[3]))
# trace plain with D and measures; no fuel, path set to avoid cycles in recording
def run(E,A,B,path=None,edges=None):
 if path is None: path=set()
 if edges is None: edges=[]
 key=(tuple(E),A,B)
 if key in path: return False
 path=path|{key}
 if not wf_env(E): return False
 if B==TOP: return wf_dec(E,A)
 if A==NAT: return B==NAT
 if A[0]=='v':
  if A==B and wf_dec(E,A): return True
  best=False
  for U in [U for (Y,k,U) in E if Y==A[1] and k=='sub']:
   edges.append(('trans',E,A,B,E,U,B,A[1])); 
   if run(E,U,B,path,edges): best=True; break
  return best
 if A[0]=='arr' and B[0]=='arr':
  edges.append(('arrow',E,A,B,E,B[1],A[1],None))
  if not run(E,B[1],A[1],path,edges): return False
  edges.append(('arrow',E,A,B,E,A[2],B[2],None)); return run(E,A[2],B[2],path,edges)
 if A[0]=='all' and B[0]=='all':
  S1,T1=A[1],A[2]; S2,T2=B[1],B[2]
  edges.append(('all',E,A,B,E,S1,S2,None))
  if not run(E,S1,S2,path,edges): return False
  edges.append(('all',E,A,B,E,S2,S1,None))
  if not run(E,S2,S1,path,edges): return False
  X=fresh(atoms_env(E)|atoms_of(A)|atoms_of(B)); E2=[(X,'sub',S2)]+E
  edges.append(('allbody',E,A,B,E2,open_tt(T1,v(X)),open_tt(T2,v(X)),None))
  return run(E2,open_tt(T1,v(X)),open_tt(T2,v(X)),path,edges)
 if A[0]=='mu' and B[0]=='mu':
  A1,A2=A[1],B[1]
  if not (wf_dec(E,A) and wf_dec(E,B)): return False
  X=fresh(atoms_env(E)|atoms_of(A)|atoms_of(B)); E2=[(X,'sub',TOP)]+E
  P1=open_tt(A1,v(X)); P2=open_tt(A2,v(X)); U1=open_tt(A1,lab(X,P1)); U2=open_tt(A2,lab(X,P2))
  if not (wf_dec(E2,P1) and wf_dec(E2,P2)): return False
  edges.append(('mu',E,A,B,E2,U1,U2,None))
  return run(E2,U1,U2,path|set(),edges)
 if A[0]=='lab' and B[0]=='lab' and A[1]==B[1]:
  edges.append(('lab',E,A,B,E,A[2],B[2],None)); return run(E,A[2],B[2],path,edges)
 if rt_type(A) and rt_type(B):
  if not (collectLabel(B)<=collectLabel(A) and wf_dec(E,A) and wf_dec(E,B)): return False
  for i in sorted(collectLabel(B)):
