 def MD(E,A,B,D): return md(A)+md(B)+sum(md(U) for (Y,k,U) in E if Y not in D)
 def RD(E,A,B,D): return raw(A)+raw(B)+sum(raw(U) for (Y,k,U) in E if Y not in D)
