from measure_checked import *
def WB(E,T):
    def go(E,T):
        t=T[0]
        if t in ('nat','top','nil','b'): return 1
        if t=='v':
            bb=binds(E,T[1]); return 1+(go(E,bb[1]) if bb is not None else 0)
        if t in ('arr','all'): return 1+go(E,T[1])+go(E,T[2])
        if t=='mu': return 1+go(E,T[1])
        if t=='lab': return 1 if T[1] in set() else 1+go(E,T[2])  # transparent labels
        return 1+go(E,T[2])+go(E,T[3])
    return go(E,T)
# use label transparent (Sig ignored)
def base(E,A,B): return WB(E,A)+WB(E,B)
def check(cases):
    bad={}; tot={}
    for (E,A,B) in cases:
        r,edges=instrument(E,A,B,set())
        for e in edges:
            k=e['kind']
            if k=='assert': continue
            if k=='oblig':
                ps=(e['sig'],e['E'],e['A'],e['B']); cs=(frozenset(),e['cE'],e['cA'],e['cB'])
                pm=base(ps[1],ps[2],ps[3])+WB(e['E2'],e['U1'])+WB(e['E2'],e['U2'])
                cm=base(cs[1],cs[2],cs[3])
            else:
                ps=(e['sig'],e['E'],e['A'],e['B']); cs=(e['csig'],e['cE'],e['cA'],e['cB'])
                pm=base(ps[1],ps[2],ps[3])
                if k=='mu': pm+=WB(e['cE'],e['cA'])+WB(e['cE'],e['cB'])
                if k=='allbody': pm+=WB(cs[1],cs[2])+WB(cs[1],cs[3])
                cm=base(cs[1],cs[2],cs[3])
