def typ_feats(Sig,T):
    # return dict features for one type
    def walk(T,depth):
        t=T[0]
        if t in ('nat','top','nil'): return {'raw':1,'height':1,'sumdep':0,'maxdep':0}
        if t in ('b','v'):
            d={'raw':1,'height':1,'sumdep':0,'maxdep':0}
            d['bvar' if t=='b' else 'fvar']=1; return d
        if t in ('arr','all'):
            d1=walk(T[1],depth); d2=walk(T[2],depth); d={}
            for k in set(d1)|set(d2): d[k]=d1.get(k,0)+d2.get(k,0)
            d['raw']=1+d.get('raw',0); d['height']=1+max(d1.get('height',0),d2.get('height',0)); d['sumdep']=d.get('sumdep',0); d['maxdep']=max(d1.get('maxdep',0),d2.get('maxdep',0)); return d
        if t=='mu':
            d=walk(T[1],depth+1); d['raw']=1+d.get('raw',0); d['height']=1+d.get('height',0); d['mu']=1+d.get('mu',0); d['sumdep']=d.get('sumdep',0)+d.get('raw0',0) if False else d.get('sumdep',0); d['maxdep']=max(d.get('maxdep',0),1); return d
        if t=='lab':
            d=walk(T[2],depth+1); d['raw']=1+d.get('raw',0); d['height']=1+d.get('height',0); d['lab']=1+d.get('lab',0)
            if T[1] in Sig: d['actlab']=1+d.get('actlab',0)
            else:
                d['inactlab']=1+d.get('inactlab',0)
                # payload raw/height under inactive label counts still
                d['inflabraw']=d.get('inflabraw',0)+d.get('raw',0)
            return d
        d1=walk(T[2],depth); d2=walk(T[3],depth); d={}
        for k in set(d1)|set(d2): d[k]=d1.get(k,0)+d2.get(k,0)
        d['raw']=1+d.get('raw',0); d['height']=1+max(d1.get('height',0),d2.get('height',0)); return d
    return walk(T,0)
def feats(Sig,E,A,B):
    S=set(Sig); d=typ_feats(S,A); e=typ_feats(S,B)
